            ["_io.BytesIO"] = "BytesIO(initial_bytes=b'')\n--\n\nBuffered I/O implementation using an in-memory bytes buffer.",
            ["_io.BytesIO.__init__"] = "__init__($self, /, *args, **kwargs)\n--\n\nInitialize self.  See help(type(self)) for accurate signature.",
            ["_io.BytesIO.__iter__"] = "__iter__($self, /)\n--\n\nImplement iter(self).",
            ["_io.BytesIO.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["_io.BytesIO.__next__"] = "__next__($self, /)\n--\n\nImplement next(self).",
            ["_io.BytesIO.close"] = "close($self, /)\n--\n\nDisable all I/O operations.",
            ["_io.BytesIO.closed"] = "True if the file is closed.",
            ["_io.BytesIO.flush"] = "flush($self, /)\n--\n\nDoes nothing.",
            ["_io.BytesIO.getbuffer"] = "getbuffer($self, /)\n--\n\nGet a read-write view over the contents of the BytesIO object.",
            ["_io.BytesIO.getvalue"] = "getvalue($self, /)\n--\n\nRetrieve the entire contents of the BytesIO object.",
            ["_io.BytesIO.isatty"] = "isatty($self, /)\n--\n\nAlways returns False.\n\nBytesIO objects are not connected to a TTY-like device.",
            ["_io.BytesIO.read"] = "read($self, size=-1, /)\n--\n\nRead at most size bytes, returned as a bytes object.\n\nIf the size argument is negative, read until EOF is reached.\nReturn an empty bytes object at EOF.",
            ["_io.BytesIO.read1"] = "read1($self, size=-1, /)\n--\n\nRead at most size bytes, returned as a bytes object.\n\nIf the size argument is negative or omitted, read until EOF is reached.\nReturn an empty bytes object at EOF.",
            ["_io.BytesIO.readable"] = "readable($self, /)\n--\n\nReturns True if the IO object can be read.",
            ["_io.BytesIO.readinto"] = "readinto($self, buffer, /)\n--\n\nRead bytes into buffer.\n\nReturns number of bytes read (0 for EOF), or None if the object\nis set not to block and has no data to read.",
            ["_io.BytesIO.readline"] = "readline($self, size=-1, /)\n--\n\nNext line from the file, as a bytes object.\n\nRetain newline.  A non-negative size argument limits the maximum\nnumber of bytes to return (an incomplete line may be returned then).\nReturn an empty bytes object at EOF.",
            ["_io.BytesIO.readlines"] = "readlines($self, size=None, /)\n--\n\nList of bytes objects, each a line from the file.\n\nCall readline() repeatedly and return a list of the lines so read.\nThe optional size argument, if given, is an approximate bound on the\ntotal number of bytes in the lines returned.",
            ["_io.BytesIO.seek"] = "seek($self, pos, whence=0, /)\n--\n\nChange stream position.\n\nSeek to byte offset pos relative to position indicated by whence:\n     0  Start of stream (the default).  pos should be >= 0;\n     1  Current position - pos may be negative;\n     2  End of stream - pos usually negative.\nReturns the new absolute position.",
            ["_io.BytesIO.seekable"] = "seekable($self, /)\n--\n\nReturns True if the IO object can be seeked.",
            ["_io.BytesIO.tell"] = "tell($self, /)\n--\n\nCurrent file position, an integer.",
            ["_io.BytesIO.truncate"] = "truncate($self, size=None, /)\n--\n\nTruncate the file to at most size bytes.\n\nSize defaults to the current file position, as returned by tell().\nThe current file position is unchanged.  Returns the new size.",
            ["_io.BytesIO.writable"] = "writable($self, /)\n--\n\nReturns True if the IO object can be written.",
            ["_io.BytesIO.write"] = "write($self, b, /)\n--\n\nWrite bytes to file.\n\nReturn the number of bytes written.",
            ["_io.BytesIO.writelines"] = "writelines($self, lines, /)\n--\n\nWrite lines to the file.\n\nNote that newlines are not added.  lines can be any iterable object\nproducing bytes-like objects. This is equivalent to calling write() for\neach element.",
            ["_io.FileIO"] = "FileIO(file, mode='r', closefd=True, opener=None)\n--\n\nOpen a file.\n\nThe mode can be 'r' (default), 'w', 'x' or 'a' for reading,\nwriting, exclusive creation or appending.  The file will be created if it\ndoesn't exist when opened for writing or appending; it will be truncated\nwhen opened for writing.  A FileExistsError will be raised if it already\nexists when opened for creating. Opening a file for creating implies\nwriting so this mode behaves in a similar way to 'w'.Add a '+' to the mode\nto allow simultaneous reading and writing. A custom opener can be used by\npassing a callable as *opener*. The underlying file descriptor for the file\nobject is then obtained by calling opener with (*name*, *flags*).\n*opener* must return an open file descriptor (passing os.open as *opener*\nresults in functionality similar to passing None).",
            ["_io.FileIO.__init__"] = "__init__($self, /, *args, **kwargs)\n--\n\nInitialize self.  See help(type(self)) for accurate signature.",
            ["_io.FileIO.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["_io.FileIO.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["_io.FileIO.close"] = "close($self, /)\n--\n\nClose the file.\n\nA closed file cannot be used for further I/O operations.  close() may be\ncalled more than once without error.",
            ["_io.FileIO.closed"] = "True if the file is closed",
            ["_io.FileIO.closefd"] = "True if the file descriptor will be closed by close().",
            ["_io.FileIO.fileno"] = "fileno($self, /)\n--\n\nReturn the underlying file descriptor (an integer).",
            ["_io.FileIO.isatty"] = "isatty($self, /)\n--\n\nTrue if the file is connected to a TTY device.",
            ["_io.FileIO.mode"] = "String giving the file mode",
            ["_io.FileIO.read"] = "read($self, size=-1, /)\n--\n\nRead at most size bytes, returned as bytes.\n\nOnly makes one system call, so less data may be returned than requested.\nIn non-blocking mode, returns None if no data is available.\nReturn an empty bytes object at EOF.",
            ["_io.FileIO.readable"] = "readable($self, /)\n--\n\nTrue if file was opened in a read mode.",
            ["_io.FileIO.readall"] = "readall($self, /)\n--\n\nRead all data from the file, returned as bytes.\n\nIn non-blocking mode, returns as much as is immediately available,\nor None if no data is available.  Return an empty bytes object at EOF.",
            ["_io.FileIO.readinto"] = "readinto($self, buffer, /)\n--\n\nSame as RawIOBase.readinto().",
            ["_io.FileIO.seek"] = "seek($self, pos, whence=0, /)\n--\n\nMove to new file position and return the file position.\n\nArgument offset is a byte count.  Optional argument whence defaults to\nSEEK_SET or 0 (offset from start of file, offset should be >= 0); other values\nare SEEK_CUR or 1 (move relative to current position, positive or negative),\nand SEEK_END or 2 (move relative to end of file, usually negative, although\nmany platforms allow seeking beyond the end of a file).\n\nNote that not all file objects are seekable.",
            ["_io.FileIO.seekable"] = "seekable($self, /)\n--\n\nTrue if file supports random-access.",
            ["_io.FileIO.tell"] = "tell($self, /)\n--\n\nCurrent file position.\n\nCan raise OSError for non seekable files.",
            ["_io.FileIO.truncate"] = "truncate($self, size=None, /)\n--\n\nTruncate the file to at most size bytes and return the truncated size.\n\nSize defaults to the current file position, as returned by tell().\nThe current file position is changed to the value of size.",
            ["_io.FileIO.writable"] = "writable($self, /)\n--\n\nTrue if file was opened in a write mode.",
            ["_io.FileIO.write"] = "write($self, b, /)\n--\n\nWrite buffer b to file, return number of bytes written.\n\nOnly makes one system call, so not all of the data may be written.\nThe number of bytes actually written is returned.  In non-blocking mode,\nreturns None if the write would block.",
            ["_io.IncrementalNewlineDecoder"] = "IncrementalNewlineDecoder(decoder, translate, errors='strict')\n--\n\nCodec used when reading a file in universal newlines mode.\n\nIt wraps another incremental decoder, translating \\r\\n and \\r into \\n.\nIt also records the types of newlines encountered.  When used with\ntranslate=False, it ensures that the newline sequence is returned in\none piece. When used with decoder=None, it expects unicode strings as\ndecode input and translates newlines without first invoking an external\ndecoder.",
            ["_io.IncrementalNewlineDecoder.__init__"] = "__init__($self, /, *args, **kwargs)\n--\n\nInitialize self.  See help(type(self)) for accurate signature.",
            ["_io.IncrementalNewlineDecoder.decode"] = "decode($self, /, input, final=False)\n--\n\n",
            ["_io.IncrementalNewlineDecoder.getstate"] = "getstate($self, /)\n--\n\n",
            ["_io.IncrementalNewlineDecoder.reset"] = "reset($self, /)\n--\n\n",
            ["_io.IncrementalNewlineDecoder.setstate"] = "setstate($self, state, /)\n--\n\n",
            ["_io.StringIO"] = "StringIO(initial_value='', newline='\\n')\n--\n\nText I/O implementation using an in-memory buffer.\n\nThe initial_value argument sets the value of object.  The newline\nargument is like the one of TextIOWrapper's constructor.",
            ["_io.StringIO.__init__"] = "__init__($self, /, *args, **kwargs)\n--\n\nInitialize self.  See help(type(self)) for accurate signature.",
            ["_io.StringIO.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["_io.StringIO.__next__"] = "__next__($self, /)\n--\n\nImplement next(self).",
            ["_io.StringIO.close"] = "close($self, /)\n--\n\nClose the IO object.\n\nAttempting any further operation after the object is closed\nwill raise a ValueError.\n\nThis method has no effect if the file is already closed.",
            ["_io.StringIO.getvalue"] = "getvalue($self, /)\n--\n\nRetrieve the entire contents of the object.",
            ["_io.StringIO.read"] = "read($self, size=-1, /)\n--\n\nRead at most size characters, returned as a string.\n\nIf the argument is negative or omitted, read until EOF\nis reached. Return an empty string at EOF.",
            ["_io.StringIO.readable"] = "readable($self, /)\n--\n\nReturns True if the IO object can be read.",
            ["_io.StringIO.readline"] = "readline($self, size=-1, /)\n--\n\nRead until newline or EOF.\n\nReturns an empty string if EOF is hit immediately.",
            ["_io.StringIO.seek"] = "seek($self, pos, whence=0, /)\n--\n\nChange stream position.\n\nSeek to character offset pos relative to position indicated by whence:\n    0  Start of stream (the default).  pos should be >= 0;\n    1  Current position - pos must be 0;\n    2  End of stream - pos must be 0.\nReturns the new absolute position.",
            ["_io.StringIO.seekable"] = "seekable($self, /)\n--\n\nReturns True if the IO object can be seeked.",
            ["_io.StringIO.tell"] = "tell($self, /)\n--\n\nTell the current file position.",
            ["_io.StringIO.truncate"] = "truncate($self, pos=None, /)\n--\n\nTruncate size to pos.\n\nThe pos argument defaults to the current file position, as\nreturned by tell().  The current file position is unchanged.\nReturns the new absolute position.",
            ["_io.StringIO.writable"] = "writable($self, /)\n--\n\nReturns True if the IO object can be written.",
            ["_io.StringIO.write"] = "write($self, s, /)\n--\n\nWrite string to file.\n\nReturns the number of characters written, which is always equal to\nthe length of the string.",
            ["_io.TextIOWrapper"] = "TextIOWrapper(buffer, encoding=None, errors=None, newline=None,\n              line_buffering=False, write_through=False)\n--\n\nCharacter and line based layer over a BufferedIOBase object, buffer.\n\nencoding gives the name of the encoding that the stream will be\ndecoded or encoded with. It defaults to locale.getencoding().\n\nerrors determines the strictness of encoding and decoding (see\nhelp(codecs.Codec) or the documentation for codecs.register) and\ndefaults to \"strict\".\n\nnewline controls how line endings are handled. It can be None, '',\n'\\n', '\\r', and '\\r\\n'.  It works as follows:\n\n* On input, if newline is None, universal newlines mode is\n  enabled. Lines in the input can end in '\\n', '\\r', or '\\r\\n', and\n  these are translated into '\\n' before being returned to the\n  caller. If it is '', universal newline mode is enabled, but line\n  endings are returned to the caller untranslated. If it has any of\n  the other legal values, input lines are only terminated by the given\n  string, and the line ending is returned to the caller untranslated.\n\n* On output, if newline is None, any '\\n' characters written are\n  translated to the system default line separator, os.linesep. If\n  newline is '' or '\\n', no translation takes place. If newline is any\n  of the other legal values, any '\\n' characters written are translated\n  to the given string.\n\nIf line_buffering is True, a call to flush is implied when a call to\nwrite contains a newline character.",
            ["_io.TextIOWrapper.__init__"] = "__init__($self, /, *args, **kwargs)\n--\n\nInitialize self.  See help(type(self)) for accurate signature.",
            ["_io.TextIOWrapper.__next__"] = "__next__($self, /)\n--\n\nImplement next(self).",
            ["_io.TextIOWrapper.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["_io.TextIOWrapper.close"] = "close($self, /)\n--\n\n",
            ["_io.TextIOWrapper.detach"] = "detach($self, /)\n--\n\n",
            ["_io.TextIOWrapper.fileno"] = "fileno($self, /)\n--\n\n",
            ["_io.TextIOWrapper.flush"] = "flush($self, /)\n--\n\n",
            ["_io.TextIOWrapper.isatty"] = "isatty($self, /)\n--\n\n",
            ["_io.TextIOWrapper.read"] = "read($self, size=-1, /)\n--\n\n",
            ["_io.TextIOWrapper.readable"] = "readable($self, /)\n--\n\n",
            ["_io.TextIOWrapper.readline"] = "readline($self, size=-1, /)\n--\n\n",
            ["_io.TextIOWrapper.reconfigure"] = "reconfigure($self, /, *, encoding=None, errors=None, newline=None,\n            line_buffering=None, write_through=None)\n--\n\nReconfigure the text stream with new parameters.\n\nThis also does an implicit stream flush.",
            ["_io.TextIOWrapper.seek"] = "seek($self, cookie, whence=os.SEEK_SET, /)\n--\n\nSet the stream position, and return the new stream position.\n\n  cookie\n    Zero or an opaque number returned by tell().\n  whence\n    The relative position to seek from.\n\nFour operations are supported, given by the following argument\ncombinations:\n\n- seek(0, SEEK_SET): Rewind to the start of the stream.\n- seek(cookie, SEEK_SET): Restore a previous position;\n  'cookie' must be a number returned by tell().\n- seek(0, SEEK_END): Fast-forward to the end of the stream.\n- seek(0, SEEK_CUR): Leave the current stream position unchanged.\n\nAny other argument combinations are invalid,\nand may raise exceptions.",
            ["_io.TextIOWrapper.seekable"] = "seekable($self, /)\n--\n\n",
            ["_io.TextIOWrapper.tell"] = "tell($self, /)\n--\n\nReturn the stream position as an opaque number.\n\nThe return value of tell() can be given as input to seek(), to restore a\nprevious stream position.",
            ["_io.TextIOWrapper.truncate"] = "truncate($self, pos=None, /)\n--\n\n",
            ["_io.TextIOWrapper.writable"] = "writable($self, /)\n--\n\n",
            ["_io.TextIOWrapper.write"] = "write($self, text, /)\n--\n\n",
            ["_io._BufferedIOBase"] = "Base class for buffered IO objects.\n\nThe main difference with RawIOBase is that the read() method\nsupports omitting the size argument, and does not have a default\nimplementation that defers to readinto().\n\nIn addition, read(), readinto() and write() may raise\nBlockingIOError if the underlying raw stream is in non-blocking\nmode and not ready; unlike their raw counterparts, they will never\nreturn None.\n\nA typical implementation should not inherit from a RawIOBase\nimplementation, but wrap one.\n",
            ["_io._BufferedIOBase.detach"] = "detach($self, /)\n--\n\nDisconnect this buffer from its underlying raw stream and return it.\n\nAfter the raw stream has been detached, the buffer is in an unusable\nstate.",
            ["_io._BufferedIOBase.read"] = "read($self, size=-1, /)\n--\n\nRead and return up to n bytes.\n\nIf the size argument is omitted, None, or negative, read and\nreturn all data until EOF.\n\nIf the size argument is positive, and the underlying raw stream is\nnot 'interactive', multiple raw reads may be issued to satisfy\nthe byte count (unless EOF is reached first).\nHowever, for interactive raw streams (as well as sockets and pipes),\nat most one raw read will be issued, and a short result does not\nimply that EOF is imminent.\n\nReturn an empty bytes object on EOF.\n\nReturn None if the underlying raw stream was open in non-blocking\nmode and no data is available at the moment.",
            ["_io._BufferedIOBase.read1"] = "read1($self, size=-1, /)\n--\n\nRead and return up to size bytes, with at most one read() call to the underlying raw stream.\n\nReturn an empty bytes object on EOF.\nA short result does not imply that EOF is imminent.",
            ["_io._BufferedIOBase.readinto"] = "readinto($self, buffer, /)\n--\n\n",
            ["_io._BufferedIOBase.readinto1"] = "readinto1($self, buffer, /)\n--\n\n",
            ["_io._BufferedIOBase.write"] = "write($self, b, /)\n--\n\nWrite buffer b to the IO stream.\n\nReturn the number of bytes written, which is always\nthe length of b in bytes.\n\nRaise BlockingIOError if the buffer is full and the\nunderlying raw stream cannot accept more data at the moment.",
            ["_io._BytesIOBuffer.__buffer__"] = "__buffer__($self, flags, /)\n--\n\nReturn a buffer object that exposes the underlying memory of the object.",
            ["_io._BytesIOBuffer.__release_buffer__"] = "__release_buffer__($self, buffer, /)\n--\n\nRelease the buffer object that exposes the underlying memory of the object.",
            ["_io._IOBase"] = "The abstract base class for all I/O classes.\n\nThis class provides dummy implementations for many methods that\nderived classes can override selectively; the default implementations\nrepresent a file that cannot be read, written or seeked.\n\nEven though IOBase does not declare read, readinto, or write because\ntheir signatures will vary, implementations and clients should\nconsider those methods part of the interface. Also, implementations\nmay raise UnsupportedOperation when operations they do not support are\ncalled.\n\nThe basic type used for binary data read from or written to a file is\nbytes. Other bytes-like objects are accepted as method arguments too.\nIn some cases (such as readinto), a writable object is required. Text\nI/O classes work with str data.\n\nNote that calling any method (except additional calls to close(),\nwhich are ignored) on a closed stream should raise a ValueError.\n\nIOBase (and its subclasses) support the iterator protocol, meaning\nthat an IOBase object can be iterated over yielding the lines in a\nstream.\n\nIOBase also supports the :keyword:`with` statement. In this example,\nfp is closed after the suite of the with statement is complete:\n\nwith open('spam.txt', 'r') as fp:\n    fp.write('Spam and eggs!')\n",
            ["_io._IOBase.__iter__"] = "__iter__($self, /)\n--\n\nImplement iter(self).",
            ["_io._IOBase.__next__"] = "__next__($self, /)\n--\n\nImplement next(self).",
            ["_io._IOBase.close"] = "close($self, /)\n--\n\nFlush and close the IO object.\n\nThis method has no effect if the file is already closed.",
            ["_io._IOBase.fileno"] = "fileno($self, /)\n--\n\nReturn underlying file descriptor if one exists.\n\nRaise OSError if the IO object does not use a file descriptor.",
            ["_io._IOBase.flush"] = "flush($self, /)\n--\n\nFlush write buffers, if applicable.\n\nThis is not implemented for read-only and non-blocking streams.",
            ["_io._IOBase.isatty"] = "isatty($self, /)\n--\n\nReturn whether this is an 'interactive' stream.\n\nReturn False if it can't be determined.",
            ["_io._IOBase.readable"] = "readable($self, /)\n--\n\nReturn whether object was opened for reading.\n\nIf False, read() will raise OSError.",
            ["_io._IOBase.readline"] = "readline($self, size=-1, /)\n--\n\nRead and return a line from the stream.\n\nIf size is specified, at most size bytes will be read.\n\nThe line terminator is always b'\\n' for binary files; for text\nfiles, the newlines argument to open can be used to select the line\nterminator(s) recognized.",
            ["_io._IOBase.readlines"] = "readlines($self, hint=-1, /)\n--\n\nReturn a list of lines from the stream.\n\nhint can be specified to control the number of lines read: no more\nlines will be read if the total size (in bytes/characters) of all\nlines so far exceeds hint.",
            ["_io._IOBase.seek"] = "seek($self, offset, whence=os.SEEK_SET, /)\n--\n\nChange the stream position to the given byte offset.\n\n  offset\n    The stream position, relative to 'whence'.\n  whence\n    The relative position to seek from.\n\nThe offset is interpreted relative to the position indicated by whence.\nValues for whence are:\n\n* os.SEEK_SET or 0 -- start of stream (the default); offset should be zero or positive\n* os.SEEK_CUR or 1 -- current stream position; offset may be negative\n* os.SEEK_END or 2 -- end of stream; offset is usually negative\n\nReturn the new absolute position.",
            ["_io._IOBase.seekable"] = "seekable($self, /)\n--\n\nReturn whether object supports random access.\n\nIf False, seek(), tell() and truncate() will raise OSError.\nThis method may need to do a test seek().",
            ["_io._IOBase.tell"] = "tell($self, /)\n--\n\nReturn current stream position.",
            ["_io._IOBase.truncate"] = "truncate($self, size=None, /)\n--\n\nTruncate file to size bytes.\n\nFile pointer is left unchanged. Size defaults to the current IO position\nas reported by tell(). Return the new size.",
            ["_io._IOBase.writable"] = "writable($self, /)\n--\n\nReturn whether object was opened for writing.\n\nIf False, write() will raise OSError.",
            ["_io._IOBase.writelines"] = "writelines($self, lines, /)\n--\n\nWrite a list of lines to stream.\n\nLine separators are not added, so it is usual for each of the\nlines provided to have a line separator at the end.",
            ["_io._RawIOBase"] = "Base class for raw binary I/O.",
            ["_io._RawIOBase.read"] = "read($self, size=-1, /)\n--\n\n",
            ["_io._RawIOBase.readall"] = "readall($self, /)\n--\n\nRead until EOF, using multiple read() call.",
            ["_io._TextIOBase"] = "Base class for text I/O.\n\nThis class provides a character and line based interface to stream\nI/O. There is no readinto method because Python's character strings\nare immutable.\n",
            ["_io._TextIOBase.detach"] = "detach($self, /)\n--\n\nSeparate the underlying buffer from the TextIOBase and return it.\n\nAfter the underlying buffer has been detached, the TextIO is in an unusable state.",
            ["_io._TextIOBase.encoding"] = "Encoding of the text stream.\n\nSubclasses should override.\n",
            ["_io._TextIOBase.errors"] = "The error setting of the decoder or encoder.\n\nSubclasses should override.\n",
            ["_io._TextIOBase.newlines"] = "Line endings translated so far.\n\nOnly line endings translated during reading are considered.\n\nSubclasses should override.\n",
            ["_io._TextIOBase.read"] = "read($self, size=-1, /)\n--\n\nRead at most size characters from stream.\n\nRead from underlying buffer until we have size characters or we hit EOF.\nIf size is negative or omitted, read until EOF.",
            ["_io._TextIOBase.readline"] = "readline($self, size=-1, /)\n--\n\nRead until newline or EOF.\n\nReturn an empty string if EOF is hit immediately.\nIf size is specified, at most size characters will be read.",
            ["_io._TextIOBase.write"] = "write($self, s, /)\n--\n\nWrite string s to stream.\n\nReturn the number of characters written\n(which is always equal to the length of the string).",
            ["_io._WindowsConsoleIO"] = "_WindowsConsoleIO(file, mode='r', closefd=True, opener=None)\n--\n\nOpen a console buffer by file descriptor.\n\nThe mode can be 'rb' (default), or 'wb' for reading or writing bytes. All\nother mode characters will be ignored. Mode 'b' will be assumed if it is\nomitted. The *opener* parameter is always ignored.",
            ["_io._WindowsConsoleIO.__getattribute__"] = "__getattribute__($self, name, /)\n--\n\nReturn getattr(self, name).",
            ["_io._WindowsConsoleIO.__init__"] = "__init__($self, /, *args, **kwargs)\n--\n\nInitialize self.  See help(type(self)) for accurate signature.",
            ["_io._WindowsConsoleIO.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["_io._WindowsConsoleIO.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["_io._WindowsConsoleIO.close"] = "close($self, /)\n--\n\nClose the console object.\n\nA closed console object cannot be used for further I/O operations.\nclose() may be called more than once without error.",
            ["_io._WindowsConsoleIO.closed"] = "True if the file is closed",
            ["_io._WindowsConsoleIO.closefd"] = "True if the file descriptor will be closed by close().",
            ["_io._WindowsConsoleIO.fileno"] = "fileno($self, /)\n--\n\nReturn the underlying file descriptor (an integer).",
            ["_io._WindowsConsoleIO.isatty"] = "isatty($self, /)\n--\n\nAlways True.",
            ["_io._WindowsConsoleIO.mode"] = "String giving the file mode",
            ["_io._WindowsConsoleIO.read"] = "read($self, size=-1, /)\n--\n\nRead at most size bytes, returned as bytes.\n\nOnly makes one system call when size is a positive integer,\nso less data may be returned than requested.\nReturn an empty bytes object at EOF.",
            ["_io._WindowsConsoleIO.readable"] = "readable($self, /)\n--\n\nTrue if console is an input buffer.",
            ["_io._WindowsConsoleIO.readall"] = "readall($self, /)\n--\n\nRead all data from the console, returned as bytes.\n\nReturn an empty bytes object at EOF.",
            ["_io._WindowsConsoleIO.readinto"] = "readinto($self, buffer, /)\n--\n\nSame as RawIOBase.readinto().",
            ["_io._WindowsConsoleIO.writable"] = "writable($self, /)\n--\n\nTrue if console is an output buffer.",
            ["_io._WindowsConsoleIO.write"] = "write($self, b, /)\n--\n\nWrite buffer b to file, return number of bytes written.\n\nOnly makes one system call, so not all of the data may be written.\nThe number of bytes actually written is returned.",
            ["_io.__doc__"] = "The io module provides the Python interfaces to stream handling. The\nbuiltin open function is defined in this module.\n\nAt the top of the I/O hierarchy is the abstract base class IOBase. It\ndefines the basic interface to a stream. Note, however, that there is no\nseparation between reading and writing to streams; implementations are\nallowed to raise an OSError if they do not support a given operation.\n\nExtending IOBase is RawIOBase which deals simply with the reading and\nwriting of raw bytes to a stream. FileIO subclasses RawIOBase to provide\nan interface to OS files.\n\nBufferedIOBase deals with buffering on a raw byte stream (RawIOBase). Its\nsubclasses, BufferedWriter, BufferedReader, and BufferedRWPair buffer\nstreams that are readable, writable, and both respectively.\nBufferedRandom provides a buffered interface to random access\nstreams. BytesIO is a simple stream of in-memory bytes.\n\nAnother IOBase subclass, TextIOBase, deals with the encoding and decoding\nof streams into text. TextIOWrapper, which extends it, is a buffered text\ninterface to a buffered raw stream (`BufferedIOBase`). Finally, StringIO\nis an in-memory stream for text.\n\nArgument names are not part of the specification, and only the arguments\nof open() are intended to be used as keyword arguments.\n\ndata:\n\nDEFAULT_BUFFER_SIZE\n\n   An int containing the default buffer size used by the module's buffered\n   I/O classes. open() uses the file's blksize (as obtained by os.stat) if\n   possible.\n",
            ["_io.open"] = "open($module, /, file, mode='r', buffering=-1, encoding=None,\n     errors=None, newline=None, closefd=True, opener=None)\n--\n\nOpen file and return a stream.  Raise OSError upon failure.\n\nfile is either a text or byte string giving the name (and the path\nif the file isn't in the current working directory) of the file to\nbe opened or an integer file descriptor of the file to be\nwrapped. (If a file descriptor is given, it is closed when the\nreturned I/O object is closed, unless closefd is set to False.)\n\nmode is an optional string that specifies the mode in which the file\nis opened. It defaults to 'r' which means open for reading in text\nmode.  Other common values are 'w' for writing (truncating the file if\nit already exists), 'x' for creating and writing to a new file, and\n'a' for appending (which on some Unix systems, means that all writes\nappend to the end of the file regardless of the current seek position).\nIn text mode, if encoding is not specified the encoding used is platform\ndependent: locale.getencoding() is called to get the current locale encoding.\n(For reading and writing raw bytes use binary mode and leave encoding\nunspecified.) The available modes are:\n\n========= ===============================================================\nCharacter Meaning\n--------- ---------------------------------------------------------------\n'r'       open for reading (default)\n'w'       open for writing, truncating the file first\n'x'       create a new file and open it for writing\n'a'       open for writing, appending to the end of the file if it exists\n'b'       binary mode\n't'       text mode (default)\n'+'       open a disk file for updating (reading and writing)\n========= ===============================================================\n\nThe default mode is 'rt' (open for reading text). For binary random\naccess, the mode 'w+b' opens and truncates the file to 0 bytes, while\n'r+b' opens the file without truncation. The 'x' mode implies 'w' and\nraises an `FileExistsError` if the file already exists.\n\nPython distinguishes between files opened in binary and text modes,\neven when the underlying operating system doesn't. Files opened in\nbinary mode (appending 'b' to the mode argument) return contents as\nbytes objects without any decoding. In text mode (the default, or when\n't' is appended to the mode argument), the contents of the file are\nreturned as strings, the bytes having been first decoded using a\nplatform-dependent encoding or using the specified encoding if given.\n\nbuffering is an optional integer used to set the buffering policy.\nPass 0 to switch buffering off (only allowed in binary mode), 1 to select\nline buffering (only usable in text mode), and an integer > 1 to indicate\nthe size of a fixed-size chunk buffer.  When no buffering argument is\ngiven, the default buffering policy works as follows:\n\n* Binary files are buffered in fixed-size chunks; the size of the buffer\n  is chosen using a heuristic trying to determine the underlying device's\n  \"block size\" and falling back on `io.DEFAULT_BUFFER_SIZE`.\n  On many systems, the buffer will typically be 4096 or 8192 bytes long.\n\n* \"Interactive\" text files (files for which isatty() returns True)\n  use line buffering.  Other text files use the policy described above\n  for binary files.\n\nencoding is the name of the encoding used to decode or encode the\nfile. This should only be used in text mode. The default encoding is\nplatform dependent, but any encoding supported by Python can be\npassed.  See the codecs module for the list of supported encodings.\n\nerrors is an optional string that specifies how encoding errors are to\nbe handled---this argument should not be used in binary mode. Pass\n'strict' to raise a ValueError exception if there is an encoding error\n(the default of None has the same effect), or pass 'ignore' to ignore\nerrors. (Note that ignoring encoding errors can lead to data loss.)\nSee the documentation for codecs.register or run 'help(codecs.Codec)'\nfor a list of the permitted encoding error strings.\n\nnewline controls how universal newlines works (it only applies to text\nmode). It can be None, '', '\\n', '\\r', and '\\r\\n'.  It works as\nfollows:\n\n* On input, if newline is None, universal newlines mode is\n  enabled. Lines in the input can end in '\\n', '\\r', or '\\r\\n', and\n  these are translated into '\\n' before being returned to the\n  caller. If it is '', universal newline mode is enabled, but line\n  endings are returned to the caller untranslated. If it has any of\n  the other legal values, input lines are only terminated by the given\n  string, and the line ending is returned to the caller untranslated.\n\n* On output, if newline is None, any '\\n' characters written are\n  translated to the system default line separator, os.linesep. If\n  newline is '' or '\\n', no translation takes place. If newline is any\n  of the other legal values, any '\\n' characters written are translated\n  to the given string.\n\nIf closefd is False, the underlying file descriptor will be kept open\nwhen the file is closed. This does not work when a file name is given\nand must be True in that case.\n\nA custom opener can be used by passing a callable as *opener*. The\nunderlying file descriptor for the file object is then obtained by\ncalling *opener* with (*file*, *flags*). *opener* must return an open\nfile descriptor (passing os.open as *opener* results in functionality\nsimilar to passing None).\n\nopen() returns a file object whose type depends on the mode, and\nthrough which the standard file operations such as reading and writing\nare performed. When open() is used to open a file in a text mode ('w',\n'r', 'wt', 'rt', etc.), it returns a TextIOWrapper. When used to open\na file in a binary mode, the returned class varies: in read binary\nmode, it returns a BufferedReader; in write binary and append binary\nmodes, it returns a BufferedWriter, and in read/write mode, it returns\na BufferedRandom.\n\nIt is also possible to use a string or bytearray as a file for both\nreading and writing. For strings StringIO can be used like a file\nopened in a text mode, and for bytes a BytesIO can be used like a file\nopened in a binary mode.",
            ["_io.open_code"] = "open_code($module, /, path)\n--\n\nOpens the provided file with the intent to import the contents.\n\nThis may perform extra validation beyond open(), but is otherwise interchangeable\nwith calling open(path, 'rb').",
            ["_io.text_encoding"] = "text_encoding($module, encoding, stacklevel=2, /)\n--\n\nA helper function to choose the text encoding.\n\nWhen encoding is not None, this function returns it.\nOtherwise, this function returns the default text encoding\n(i.e. \"locale\" or \"utf-8\" depends on UTF-8 mode).\n\nThis function emits an EncodingWarning if encoding is None and\nsys.flags.warn_default_encoding is true.\n\nThis can be used in APIs with an encoding=None parameter.\nHowever, please consider using encoding=\"utf-8\" for new APIs.",
            ["_operator.__doc__"] = "Operator interface.\n\nThis module exports a set of functions implemented in C corresponding\nto the intrinsic operators of Python.  For example, operator.add(x, y)\nis equivalent to the expression x+y.  The function names are those\nused for special methods; variants without leading and trailing\n'__' are also provided for convenience.",
            ["_operator.abs"] = "abs($module, a, /)\n--\n\nSame as abs(a).",
            ["_operator.add"] = "add($module, a, b, /)\n--\n\nSame as a + b.",
            ["_operator.and_"] = "and_($module, a, b, /)\n--\n\nSame as a & b.",
            ["_operator.call"] = "call($module, obj, /, *args, **kwargs)\n--\n\nSame as obj(*args, **kwargs).",
            ["_operator.concat"] = "concat($module, a, b, /)\n--\n\nSame as a + b, for a and b sequences.",
            ["_operator.contains"] = "contains($module, a, b, /)\n--\n\nSame as b in a (note reversed operands).",
            ["_operator.countOf"] = "countOf($module, a, b, /)\n--\n\nReturn the number of items in a which are, or which equal, b.",
            ["_operator.delitem"] = "delitem($module, a, b, /)\n--\n\nSame as del a[b].",
            ["_operator.eq"] = "eq($module, a, b, /)\n--\n\nSame as a == b.",
            ["_operator.floordiv"] = "floordiv($module, a, b, /)\n--\n\nSame as a // b.",
            ["_operator.ge"] = "ge($module, a, b, /)\n--\n\nSame as a >= b.",
            ["_operator.getitem"] = "getitem($module, a, b, /)\n--\n\nSame as a[b].",
            ["_operator.gt"] = "gt($module, a, b, /)\n--\n\nSame as a > b.",
            ["_operator.iadd"] = "iadd($module, a, b, /)\n--\n\nSame as a += b.",
            ["_operator.iand"] = "iand($module, a, b, /)\n--\n\nSame as a &= b.",
            ["_operator.iconcat"] = "iconcat($module, a, b, /)\n--\n\nSame as a += b, for a and b sequences.",
            ["_operator.ifloordiv"] = "ifloordiv($module, a, b, /)\n--\n\nSame as a //= b.",
            ["_operator.ilshift"] = "ilshift($module, a, b, /)\n--\n\nSame as a <<= b.",
            ["_operator.imatmul"] = "imatmul($module, a, b, /)\n--\n\nSame as a @= b.",
            ["_operator.imod"] = "imod($module, a, b, /)\n--\n\nSame as a %= b.",
            ["_operator.imul"] = "imul($module, a, b, /)\n--\n\nSame as a *= b.",
            ["_operator.index"] = "index($module, a, /)\n--\n\nSame as a.__index__()",
            ["_operator.indexOf"] = "indexOf($module, a, b, /)\n--\n\nReturn the first index of b in a.",
            ["_operator.inv"] = "inv($module, a, /)\n--\n\nSame as ~a.",
            ["_operator.invert"] = "invert($module, a, /)\n--\n\nSame as ~a.",
            ["_operator.ior"] = "ior($module, a, b, /)\n--\n\nSame as a |= b.",
            ["_operator.ipow"] = "ipow($module, a, b, /)\n--\n\nSame as a **= b.",
            ["_operator.irshift"] = "irshift($module, a, b, /)\n--\n\nSame as a >>= b.",
            ["_operator.is_"] = "is_($module, a, b, /)\n--\n\nSame as a is b.",
            ["_operator.is_not"] = "is_not($module, a, b, /)\n--\n\nSame as a is not b.",
            ["_operator.isub"] = "isub($module, a, b, /)\n--\n\nSame as a -= b.",
            ["_operator.itruediv"] = "itruediv($module, a, b, /)\n--\n\nSame as a /= b.",
            ["_operator.ixor"] = "ixor($module, a, b, /)\n--\n\nSame as a ^= b.",
            ["_operator.le"] = "le($module, a, b, /)\n--\n\nSame as a <= b.",
            ["_operator.length_hint"] = "length_hint($module, obj, default=0, /)\n--\n\nReturn an estimate of the number of items in obj.\n\nThis is useful for presizing containers when building from an iterable.\n\nIf the object supports len(), the result will be exact.\nOtherwise, it may over- or under-estimate by an arbitrary amount.\nThe result will be an integer >= 0.",
            ["_operator.lshift"] = "lshift($module, a, b, /)\n--\n\nSame as a << b.",
            ["_operator.lt"] = "lt($module, a, b, /)\n--\n\nSame as a < b.",
            ["_operator.matmul"] = "matmul($module, a, b, /)\n--\n\nSame as a @ b.",
            ["_operator.mod"] = "mod($module, a, b, /)\n--\n\nSame as a % b.",
            ["_operator.mul"] = "mul($module, a, b, /)\n--\n\nSame as a * b.",
            ["_operator.ne"] = "ne($module, a, b, /)\n--\n\nSame as a != b.",
            ["_operator.neg"] = "neg($module, a, /)\n--\n\nSame as -a.",
            ["_operator.not_"] = "not_($module, a, /)\n--\n\nSame as not a.",
