            ["_operator.pow"] = "pow($module, a, b, /)\n--\n\nSame as a ** b.",
            ["_operator.rshift"] = "rshift($module, a, b, /)\n--\n\nSame as a >> b.",
            ["_operator.setitem"] = "setitem($module, a, b, c, /)\n--\n\nSame as a[b] = c.",
