            ["_operator.truediv"] = "truediv($module, a, b, /)\n--\n\nSame as a / b.",
            ["_operator.truth"] = "truth($module, a, /)\n--\n\nReturn True if a is true, False otherwise.",
            ["_operator.xor"] = "xor($module, a, b, /)\n--\n\nSame as a ^ b.",
            ["_random.Random"] = "Random() -> create a random number generator with its own internal state.",
            ["_random.Random.__init__"] = "__init__($self, /, *args, **kwargs)\n--\n\nInitialize self.  See help(type(self)) for accurate signature.",
            ["_random.Random.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["_random.Random.getrandbits"] = "getrandbits($self, k, /)\n--\n\ngetrandbits(k) -> x.  Generates an int with k random bits.",
            ["_random.Random.getstate"] = "getstate($self, /)\n--\n\ngetstate() -> tuple containing the current state.",
            ["_random.Random.random"] = "random($self, /)\n--\n\nrandom() -> x in the interval [0, 1).",
            ["_random.Random.seed"] = "seed($self, n=None, /)\n--\n\nseed([n]) -> None.\n\nDefaults to use urandom and falls back to a combination\nof the current time and the process identifier.",
            ["_random.Random.setstate"] = "setstate($self, state, /)\n--\n\nsetstate(state) -> None.  Restores generator state.",
            ["_random.__doc__"] = "Module implements the Mersenne Twister random number generator.",
            ["_sre.SRE_Scanner.match"] = "match($self, /)\n--\n\n",
            ["_sre.SRE_Scanner.search"] = "search($self, /)\n--\n\n",
            ["_struct.Struct"] = "Struct(fmt) --> compiled struct object\n\n",
            ["_struct.Struct.__delattr__"] = "__delattr__($self, name, /)\n--\n\nImplement delattr(self, name).",
            ["_struct.Struct.__getattribute__"] = "__getattribute__($self, name, /)\n--\n\nReturn getattr(self, name).",
            ["_struct.Struct.__init__"] = "__init__($self, /, *args, **kwargs)\n--\n\nInitialize self.  See help(type(self)) for accurate signature.",
            ["_struct.Struct.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["_struct.Struct.__setattr__"] = "__setattr__($self, name, value, /)\n--\n\nImplement setattr(self, name, value).",
            ["_struct.Struct.__sizeof__"] = "S.__sizeof__() -> size of S in memory, in bytes",
            ["_struct.Struct.format"] = "struct format string",
            ["_struct.Struct.iter_unpack"] = "iter_unpack($self, buffer, /)\n--\n\nReturn an iterator yielding tuples.\n\nTuples are unpacked from the given bytes source, like a repeated\ninvocation of unpack_from().\n\nRequires that the bytes length be a multiple of the struct size.",
            ["_struct.Struct.pack"] = "S.pack(v1, v2, ...) -> bytes\n\nReturn a bytes object containing values v1, v2, ... packed according\nto the format string S.format.  See help(struct) for more on format\nstrings.",
            ["_struct.Struct.pack_into"] = "S.pack_into(buffer, offset, v1, v2, ...)\n\nPack the values v1, v2, ... according to the format string S.format\nand write the packed bytes into the writable buffer buf starting at\noffset.  Note that the offset is a required argument.  See\nhelp(struct) for more on format strings.",
            ["_struct.Struct.size"] = "struct size in bytes",
            ["_struct.Struct.unpack"] = "unpack($self, buffer, /)\n--\n\nReturn a tuple containing unpacked values.\n\nUnpack according to the format string Struct.format. The buffer's size\nin bytes must be Struct.size.\n\nSee help(struct) for more on format strings.",
            ["_struct.Struct.unpack_from"] = "unpack_from($self, /, buffer, offset=0)\n--\n\nReturn a tuple containing unpacked values.\n\nValues are unpacked according to the format string Struct.format.\n\nThe buffer's size in bytes, starting at position offset, must be\nat least Struct.size.\n\nSee help(struct) for more on format strings.",
            ["_struct.__doc__"] = "Functions to convert between Python values and C structs.\nPython bytes objects are used to hold the data representing the C struct\nand also as format strings (explained below) to describe the layout of data\nin the C struct.\n\nThe optional first format char indicates byte order, size and alignment:\n  @: native order, size & alignment (default)\n  =: native order, std. size & alignment\n  <: little-endian, std. size & alignment\n  >: big-endian, std. size & alignment\n  !: same as >\n\nThe remaining chars indicate types of args and must match exactly;\nthese can be preceded by a decimal repeat count:\n  x: pad byte (no data); c:char; b:signed byte; B:unsigned byte;\n  ?: _Bool (requires C99; if not available, char is used instead)\n  h:short; H:unsigned short; i:int; I:unsigned int;\n  l:long; L:unsigned long; f:float; d:double; e:half-float.\nSpecial cases (preceding decimal count indicates length):\n  s:string (array of char); p: pascal string (with count byte).\nSpecial cases (only available in native format):\n  n:ssize_t; N:size_t;\n  P:an integer type that is wide enough to hold a pointer.\nSpecial case (not in native mode unless 'long long' in platform C):\n  q:long long; Q:unsigned long long\nWhitespace between formats is ignored.\n\nThe variable struct.error is an exception raised on errors.\n",
            ["_struct.calcsize"] = "calcsize($module, format, /)\n--\n\nReturn size in bytes of the struct described by the format string.",
            ["_struct.iter_unpack"] = "iter_unpack($module, format, buffer, /)\n--\n\nReturn an iterator yielding tuples unpacked from the given bytes.\n\nThe bytes are unpacked according to the format string, like\na repeated invocation of unpack_from().\n\nRequires that the bytes length be a multiple of the format struct size.",
            ["_struct.pack"] = "pack(format, v1, v2, ...) -> bytes\n\nReturn a bytes object containing the values v1, v2, ... packed according\nto the format string.  See help(struct) for more on format strings.",
            ["_struct.pack_into"] = "pack_into(format, buffer, offset, v1, v2, ...)\n\nPack the values v1, v2, ... according to the format string and write\nthe packed bytes into the writable buffer buf starting at offset.  Note\nthat the offset is a required argument.  See help(struct) for more\non format strings.",
            ["_struct.unpack"] = "unpack($module, format, buffer, /)\n--\n\nReturn a tuple containing values unpacked according to the format string.\n\nThe buffer's size in bytes must be calcsize(format).\n\nSee help(struct) for more on format strings.",
            ["_struct.unpack_from"] = "unpack_from($module, format, /, buffer, offset=0)\n--\n\nReturn a tuple containing values unpacked according to the format string.\n\nThe buffer's size, minus offset, must be at least calcsize(format).\n\nSee help(struct) for more on format strings.",
            ["_thread.RLock.__enter__"] = "acquire(blocking=True) -> bool\n\nLock the lock.  `blocking` indicates whether we should wait\nfor the lock to be available or not.  If `blocking` is False\nand another thread holds the lock, the method will return False\nimmediately.  If `blocking` is True and another thread holds\nthe lock, the method will wait for the lock to be released,\ntake it and then return True.\n(note: the blocking operation is interruptible.)\n\nIn all other cases, the method will return True immediately.\nPrecisely, if the current thread already holds the lock, its\ninternal counter is simply incremented. If nobody holds the lock,\nthe lock is taken and its internal counter initialized to 1.",
            ["_thread.RLock.__exit__"] = "release()\n\nRelease the lock, allowing another thread that is blocked waiting for\nthe lock to acquire the lock.  The lock must be in the locked state,\nand must be locked by the same thread that unlocks it; otherwise a\n`RuntimeError` is raised.\n\nDo note that if the lock was acquire()d several times in a row by the\ncurrent thread, release() needs to be called as many times for the lock\nto be available for other threads.",
            ["_thread.RLock.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["_thread.RLock.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["_thread.RLock._acquire_restore"] = "_acquire_restore(state) -> None\n\nFor internal use by `threading.Condition`.",
            ["_thread.RLock._is_owned"] = "_is_owned() -> bool\n\nFor internal use by `threading.Condition`.",
            ["_thread.RLock._recursion_count"] = "_recursion_count() -> int\n\nFor internal use by reentrancy checks.",
            ["_thread.RLock._release_save"] = "_release_save() -> tuple\n\nFor internal use by `threading.Condition`.",
            ["_thread.RLock.acquire"] = "acquire(blocking=True) -> bool\n\nLock the lock.  `blocking` indicates whether we should wait\nfor the lock to be available or not.  If `blocking` is False\nand another thread holds the lock, the method will return False\nimmediately.  If `blocking` is True and another thread holds\nthe lock, the method will wait for the lock to be released,\ntake it and then return True.\n(note: the blocking operation is interruptible.)\n\nIn all other cases, the method will return True immediately.\nPrecisely, if the current thread already holds the lock, its\ninternal counter is simply incremented. If nobody holds the lock,\nthe lock is taken and its internal counter initialized to 1.",
            ["_thread.RLock.release"] = "release()\n\nRelease the lock, allowing another thread that is blocked waiting for\nthe lock to acquire the lock.  The lock must be in the locked state,\nand must be locked by the same thread that unlocks it; otherwise a\n`RuntimeError` is raised.\n\nDo note that if the lock was acquire()d several times in a row by the\ncurrent thread, release() needs to be called as many times for the lock\nto be available for other threads.",
            ["_thread._ExceptHookArgs"] = "ExceptHookArgs\n\nType used to pass arguments to threading.excepthook.",
            ["_thread._ExceptHookArgs.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["_thread._ExceptHookArgs.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["_thread._ExceptHookArgs.exc_traceback"] = "Exception traceback",
            ["_thread._ExceptHookArgs.exc_type"] = "Exception type",
            ["_thread._ExceptHookArgs.exc_value"] = "Exception value",
            ["_thread._ExceptHookArgs.thread"] = "Thread",
            ["_thread.__doc__"] = "This module provides primitive operations to write multi-threaded programs.\nThe 'threading' module provides a more convenient interface.",
            ["_thread._local"] = "Thread-local data",
            ["_thread._local.__delattr__"] = "__delattr__($self, name, /)\n--\n\nImplement delattr(self, name).",
            ["_thread._local.__getattribute__"] = "__getattribute__($self, name, /)\n--\n\nReturn getattr(self, name).",
            ["_thread._local.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["_thread._local.__setattr__"] = "__setattr__($self, name, value, /)\n--\n\nImplement setattr(self, name, value).",
            ["_thread.allocate"] = "allocate_lock() -> lock object\n(allocate() is an obsolete synonym)\n\nCreate a new lock object. See help(type(threading.Lock())) for\ninformation about locks.",
            ["_thread.allocate_lock"] = "allocate_lock() -> lock object\n(allocate() is an obsolete synonym)\n\nCreate a new lock object. See help(type(threading.Lock())) for\ninformation about locks.",
            ["_thread.daemon_threads_allowed"] = "daemon_threads_allowed()\n\nReturn True if daemon threads are allowed in the current interpreter,\nand False otherwise.\n",
            ["_thread.exit"] = "exit()\n(exit_thread() is an obsolete synonym)\n\nThis is synonymous to ``raise SystemExit''.  It will cause the current\nthread to exit silently unless the exception is caught.",
            ["_thread.exit_thread"] = "exit()\n(exit_thread() is an obsolete synonym)\n\nThis is synonymous to ``raise SystemExit''.  It will cause the current\nthread to exit silently unless the exception is caught.",
            ["_thread.get_ident"] = "get_ident() -> integer\n\nReturn a non-zero integer that uniquely identifies the current thread\namongst other threads that exist simultaneously.\nThis may be used to identify per-thread resources.\nEven though on some platforms threads identities may appear to be\nallocated consecutive numbers starting at 1, this behavior should not\nbe relied upon, and the number should be seen purely as a magic cookie.\nA thread's identity may be reused for another thread after it exits.",
            ["_thread.get_native_id"] = "get_native_id() -> integer\n\nReturn a non-negative integer identifying the thread as reported\nby the OS (kernel). This may be used to uniquely identify a\nparticular thread within a system.",
            ["_thread.interrupt_main"] = "interrupt_main(signum=signal.SIGINT, /)\n\nSimulate the arrival of the given signal in the main thread,\nwhere the corresponding signal handler will be executed.\nIf *signum* is omitted, SIGINT is assumed.\nA subthread can use this function to interrupt the main thread.\n\nNote: the default signal handler for SIGINT raises ``KeyboardInterrupt``.",
            ["_thread.lock"] = "A lock object is a synchronization primitive.  To create a lock,\ncall threading.Lock().  Methods are:\n\nacquire() -- lock the lock, possibly blocking until it can be obtained\nrelease() -- unlock of the lock\nlocked() -- test whether the lock is currently locked\n\nA lock is not owned by the thread that locked it; another thread may\nunlock it.  A thread attempting to lock a lock that it has already locked\nwill block until another thread unlocks it.  Deadlocks may ensue.",
            ["_thread.lock.__enter__"] = "acquire(blocking=True, timeout=-1) -> bool\n(acquire_lock() is an obsolete synonym)\n\nLock the lock.  Without argument, this blocks if the lock is already\nlocked (even by the same thread), waiting for another thread to release\nthe lock, and return True once the lock is acquired.\nWith an argument, this will only block if the argument is true,\nand the return value reflects whether the lock is acquired.\nThe blocking operation is interruptible.",
            ["_thread.lock.__exit__"] = "release()\n(release_lock() is an obsolete synonym)\n\nRelease the lock, allowing another thread that is blocked waiting for\nthe lock to acquire the lock.  The lock must be in the locked state,\nbut it needn't be locked by the same thread that unlocks it.",
            ["_thread.lock.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["_thread.lock.acquire"] = "acquire(blocking=True, timeout=-1) -> bool\n(acquire_lock() is an obsolete synonym)\n\nLock the lock.  Without argument, this blocks if the lock is already\nlocked (even by the same thread), waiting for another thread to release\nthe lock, and return True once the lock is acquired.\nWith an argument, this will only block if the argument is true,\nand the return value reflects whether the lock is acquired.\nThe blocking operation is interruptible.",
            ["_thread.lock.acquire_lock"] = "acquire(blocking=True, timeout=-1) -> bool\n(acquire_lock() is an obsolete synonym)\n\nLock the lock.  Without argument, this blocks if the lock is already\nlocked (even by the same thread), waiting for another thread to release\nthe lock, and return True once the lock is acquired.\nWith an argument, this will only block if the argument is true,\nand the return value reflects whether the lock is acquired.\nThe blocking operation is interruptible.",
            ["_thread.lock.locked"] = "locked() -> bool\n(locked_lock() is an obsolete synonym)\n\nReturn whether the lock is in the locked state.",
            ["_thread.lock.locked_lock"] = "locked() -> bool\n(locked_lock() is an obsolete synonym)\n\nReturn whether the lock is in the locked state.",
            ["_thread.lock.release"] = "release()\n(release_lock() is an obsolete synonym)\n\nRelease the lock, allowing another thread that is blocked waiting for\nthe lock to acquire the lock.  The lock must be in the locked state,\nbut it needn't be locked by the same thread that unlocks it.",
            ["_thread.lock.release_lock"] = "release()\n(release_lock() is an obsolete synonym)\n\nRelease the lock, allowing another thread that is blocked waiting for\nthe lock to acquire the lock.  The lock must be in the locked state,\nbut it needn't be locked by the same thread that unlocks it.",
            ["_thread.stack_size"] = "stack_size([size]) -> size\n\nReturn the thread stack size used when creating new threads.  The\noptional size argument specifies the stack size (in bytes) to be used\nfor subsequently created threads, and must be 0 (use platform or\nconfigured default) or a positive integer value of at least 32,768 (32k).\nIf changing the thread stack size is unsupported, a ThreadError\nexception is raised.  If the specified size is invalid, a ValueError\nexception is raised, and the stack size is unmodified.  32k bytes\n currently the minimum supported stack size value to guarantee\nsufficient stack space for the interpreter itself.\n\nNote that some platforms may have particular restrictions on values for\nthe stack size, such as requiring a minimum stack size larger than 32 KiB or\nrequiring allocation in multiples of the system memory page size\n- platform documentation should be referred to for more information\n(4 KiB pages are common; using multiples of 4096 for the stack size is\nthe suggested approach in the absence of more specific information).",
            ["_thread.start_new"] = "start_new_thread(function, args[, kwargs])\n(start_new() is an obsolete synonym)\n\nStart a new thread and return its identifier.  The thread will call the\nfunction with positional arguments from the tuple args and keyword arguments\ntaken from the optional dictionary kwargs.  The thread exits when the\nfunction returns; the return value is ignored.  The thread will also exit\nwhen the function raises an unhandled exception; a stack trace will be\nprinted unless the exception is SystemExit.\n",
            ["_thread.start_new_thread"] = "start_new_thread(function, args[, kwargs])\n(start_new() is an obsolete synonym)\n\nStart a new thread and return its identifier.  The thread will call the\nfunction with positional arguments from the tuple args and keyword arguments\ntaken from the optional dictionary kwargs.  The thread exits when the\nfunction returns; the return value is ignored.  The thread will also exit\nwhen the function raises an unhandled exception; a stack trace will be\nprinted unless the exception is SystemExit.\n",
            ["array.__doc__"] = "This module defines an object type which can efficiently represent\nan array of basic values: characters, integers, floating-point\nnumbers.  Arrays are sequence types and behave very much like lists,\nexcept that the type of objects stored in them is constrained.\n",
            ["array.array"] = "array(typecode [, initializer]) -> array\n\nReturn a new array whose items are restricted by typecode, and\ninitialized from the optional initializer value, which must be a list,\nstring or iterable over elements of the appropriate type.\n\nArrays represent basic values and behave very much like lists, except\nthe type of objects stored in them is constrained. The type is specified\nat object creation time by using a type code, which is a single character.\nThe following type codes are defined:\n\n    Type code   C Type             Minimum size in bytes\n    'b'         signed integer     1\n    'B'         unsigned integer   1\n    'u'         Unicode character  2 (see note)\n    'h'         signed integer     2\n    'H'         unsigned integer   2\n    'i'         signed integer     2\n    'I'         unsigned integer   2\n    'l'         signed integer     4\n    'L'         unsigned integer   4\n    'q'         signed integer     8 (see note)\n    'Q'         unsigned integer   8 (see note)\n    'f'         floating-point     4\n    'd'         floating-point     8\n\nNOTE: The 'u' typecode corresponds to Python's unicode character. On\nnarrow builds this is 2-bytes on wide builds this is 4-bytes.\n\nNOTE: The 'q' and 'Q' type codes are only available if the platform\nC compiler used to build Python supports 'long long', or, on Windows,\n'__int64'.\n\nMethods:\n\nappend() -- append a new item to the end of the array\nbuffer_info() -- return information giving the current memory info\nbyteswap() -- byteswap all the items of the array\ncount() -- return number of occurrences of an object\nextend() -- extend array by appending multiple elements from an iterable\nfromfile() -- read items from a file object\nfromlist() -- append items from the list\nfrombytes() -- append items from the string\nindex() -- return index of first occurrence of an object\ninsert() -- insert a new item into the array at a provided position\npop() -- remove and return item (default last)\nremove() -- remove first occurrence of an object\nreverse() -- reverse the order of the items in the array\ntofile() -- write all items to a file object\ntolist() -- return the array converted to an ordinary list\ntobytes() -- return the array converted to a string\n\nAttributes:\n\ntypecode -- the typecode character used to create the array\nitemsize -- the length in bytes of one array item\n",
            ["array.array.__add__"] = "__add__($self, value, /)\n--\n\nReturn self+value.",
            ["array.array.__buffer__"] = "__buffer__($self, flags, /)\n--\n\nReturn a buffer object that exposes the underlying memory of the object.",
            ["array.array.__class_getitem__"] = "See PEP 585",
            ["array.array.__contains__"] = "__contains__($self, key, /)\n--\n\nReturn bool(key in self).",
            ["array.array.__copy__"] = "__copy__($self, /)\n--\n\nReturn a copy of the array.",
            ["array.array.__deepcopy__"] = "__deepcopy__($self, unused, /)\n--\n\nReturn a copy of the array.",
            ["array.array.__delitem__"] = "__delitem__($self, key, /)\n--\n\nDelete self[key].",
            ["array.array.__eq__"] = "__eq__($self, value, /)\n--\n\nReturn self==value.",
            ["array.array.__ge__"] = "__ge__($self, value, /)\n--\n\nReturn self>=value.",
            ["array.array.__getattribute__"] = "__getattribute__($self, name, /)\n--\n\nReturn getattr(self, name).",
            ["array.array.__getitem__"] = "__getitem__($self, key, /)\n--\n\nReturn self[key].",
            ["array.array.__gt__"] = "__gt__($self, value, /)\n--\n\nReturn self>value.",
            ["array.array.__iadd__"] = "__iadd__($self, value, /)\n--\n\nImplement self+=value.",
            ["array.array.__imul__"] = "__imul__($self, value, /)\n--\n\nImplement self*=value.",
            ["array.array.__iter__"] = "__iter__($self, /)\n--\n\nImplement iter(self).",
            ["array.array.__le__"] = "__le__($self, value, /)\n--\n\nReturn self<=value.",
            ["array.array.__len__"] = "__len__($self, /)\n--\n\nReturn len(self).",
            ["array.array.__lt__"] = "__lt__($self, value, /)\n--\n\nReturn self<value.",
            ["array.array.__mul__"] = "__mul__($self, value, /)\n--\n\nReturn self*value.",
            ["array.array.__ne__"] = "__ne__($self, value, /)\n--\n\nReturn self!=value.",
            ["array.array.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["array.array.__reduce_ex__"] = "__reduce_ex__($self, value, /)\n--\n\nReturn state information for pickling.",
            ["array.array.__release_buffer__"] = "__release_buffer__($self, buffer, /)\n--\n\nRelease the buffer object that exposes the underlying memory of the object.",
            ["array.array.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["array.array.__rmul__"] = "__rmul__($self, value, /)\n--\n\nReturn value*self.",
            ["array.array.__setitem__"] = "__setitem__($self, key, value, /)\n--\n\nSet self[key] to value.",
            ["array.array.__sizeof__"] = "__sizeof__($self, /)\n--\n\nSize of the array in memory, in bytes.",
            ["array.array.append"] = "append($self, v, /)\n--\n\nAppend new value v to the end of the array.",
            ["array.array.buffer_info"] = "buffer_info($self, /)\n--\n\nReturn a tuple (address, length) giving the current memory address and the length in items of the buffer used to hold array's contents.\n\nThe length should be multiplied by the itemsize attribute to calculate\nthe buffer length in bytes.",
            ["array.array.byteswap"] = "byteswap($self, /)\n--\n\nByteswap all items of the array.\n\nIf the items in the array are not 1, 2, 4, or 8 bytes in size, RuntimeError is\nraised.",
            ["array.array.count"] = "count($self, v, /)\n--\n\nReturn number of occurrences of v in the array.",
            ["array.array.extend"] = "extend($self, bb, /)\n--\n\nAppend items to the end of the array.",
            ["array.array.frombytes"] = "frombytes($self, buffer, /)\n--\n\nAppends items from the string, interpreting it as an array of machine values, as if it had been read from a file using the fromfile() method.",
            ["array.array.fromfile"] = "fromfile($self, f, n, /)\n--\n\nRead n objects from the file object f and append them to the end of the array.",
            ["array.array.fromlist"] = "fromlist($self, list, /)\n--\n\nAppend items to array from list.",
            ["array.array.fromunicode"] = "fromunicode($self, ustr, /)\n--\n\nExtends this array with data from the unicode string ustr.\n\nThe array must be a unicode type array; otherwise a ValueError is raised.\nUse array.frombytes(ustr.encode(...)) to append Unicode data to an array of\nsome other type.",
            ["array.array.index"] = "index($self, v, start=0, stop=sys.maxsize, /)\n--\n\nReturn index of first occurrence of v in the array.\n\nRaise ValueError if the value is not present.",
            ["array.array.insert"] = "insert($self, i, v, /)\n--\n\nInsert a new item v into the array before position i.",
            ["array.array.itemsize"] = "the size, in bytes, of one array item",
            ["array.array.pop"] = "pop($self, i=-1, /)\n--\n\nReturn the i-th element and delete it from the array.\n\ni defaults to -1.",
            ["array.array.remove"] = "remove($self, v, /)\n--\n\nRemove the first occurrence of v in the array.",
            ["array.array.reverse"] = "reverse($self, /)\n--\n\nReverse the order of the items in the array.",
            ["array.array.tobytes"] = "tobytes($self, /)\n--\n\nConvert the array to an array of machine values and return the bytes representation.",
            ["array.array.tofile"] = "tofile($self, f, /)\n--\n\nWrite all items (as machine values) to the file object f.",
            ["array.array.tolist"] = "tolist($self, /)\n--\n\nConvert array to an ordinary list with the same items.",
            ["array.array.tounicode"] = "tounicode($self, /)\n--\n\nExtends this array with data from the unicode string ustr.\n\nConvert the array to a unicode string.  The array must be a unicode type array;\notherwise a ValueError is raised.  Use array.tobytes().decode() to obtain a\nunicode string from an array of some other type.",
            ["array.array.typecode"] = "the typecode character used to create the array",
            ["async_generator.__aiter__"] = "__aiter__($self, /)\n--\n\nReturn an awaitable, that resolves in asynchronous iterator.",
            ["async_generator.__anext__"] = "__anext__($self, /)\n--\n\nReturn a value or raise StopAsyncIteration.",
            ["async_generator.__class_getitem__"] = "See PEP 585",
            ["async_generator.__name__"] = "name of the async generator",
            ["async_generator.__qualname__"] = "qualified name of the async generator",
            ["async_generator.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["async_generator.__sizeof__"] = "gen.__sizeof__() -> size of gen in memory, in bytes",
            ["async_generator.aclose"] = "aclose() -> raise GeneratorExit inside generator.",
            ["async_generator.ag_await"] = "object being awaited on, or None",
            ["async_generator.asend"] = "asend(v) -> send 'v' in generator.",
            ["async_generator.athrow"] = "athrow(value)\nathrow(type[,value[,tb]])\n\nraise exception in generator.\nthe (type, val, tb) signature is deprecated, \nand may be removed in a future version of Python.",
            ["bool"] = "bool(x) -> bool\n\nReturns True when the argument x is true, False otherwise.\nThe builtins True and False are the only two instances of the class bool.\nThe class bool is a subclass of the class int, and cannot be subclassed.",
            ["bool.__and__"] = "__and__($self, value, /)\n--\n\nReturn self&value.",
            ["bool.__invert__"] = "__invert__($self, /)\n--\n\n~self",
            ["bool.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["bool.__or__"] = "__or__($self, value, /)\n--\n\nReturn self|value.",
            ["bool.__rand__"] = "__rand__($self, value, /)\n--\n\nReturn value&self.",
            ["bool.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["bool.__ror__"] = "__ror__($self, value, /)\n--\n\nReturn value|self.",
            ["bool.__rxor__"] = "__rxor__($self, value, /)\n--\n\nReturn value^self.",
            ["bool.__xor__"] = "__xor__($self, value, /)\n--\n\nReturn self^value.",
            ["builtin_function_or_method.__call__"] = "__call__($self, /, *args, **kwargs)\n--\n\nCall self as a function.",
            ["builtin_function_or_method.__eq__"] = "__eq__($self, value, /)\n--\n\nReturn self==value.",
            ["builtin_function_or_method.__ge__"] = "__ge__($self, value, /)\n--\n\nReturn self>=value.",
            ["builtin_function_or_method.__gt__"] = "__gt__($self, value, /)\n--\n\nReturn self>value.",
            ["builtin_function_or_method.__hash__"] = "__hash__($self, /)\n--\n\nReturn hash(self).",
            ["builtin_function_or_method.__le__"] = "__le__($self, value, /)\n--\n\nReturn self<=value.",
            ["builtin_function_or_method.__lt__"] = "__lt__($self, value, /)\n--\n\nReturn self<value.",
            ["builtin_function_or_method.__ne__"] = "__ne__($self, value, /)\n--\n\nReturn self!=value.",
            ["builtin_function_or_method.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["builtins.BlockingIOError"] = "I/O operation would block.",
            ["builtins.BlockingIOError.__init__"] = "__init__($self, /, *args, **kwargs)\n--\n\nInitialize self.  See help(type(self)) for accurate signature.",
            ["builtins.OSError"] = "Base class for I/O related errors.",
            ["builtins.OSError.__init__"] = "__init__($self, /, *args, **kwargs)\n--\n\nInitialize self.  See help(type(self)) for accurate signature.",
            ["builtins.OSError.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["builtins.OSError.__str__"] = "__str__($self, /)\n--\n\nReturn str(self).",
            ["builtins.OSError.errno"] = "POSIX exception code",
            ["builtins.OSError.filename"] = "exception filename",
            ["builtins.OSError.filename2"] = "second exception filename",
            ["builtins.OSError.strerror"] = "exception strerror",
            ["builtins.OSError.winerror"] = "Win32 exception code",
            ["builtins.RuntimeError"] = "Unspecified run-time error.",
            ["builtins.RuntimeError.__init__"] = "__init__($self, /, *args, **kwargs)\n--\n\nInitialize self.  See help(type(self)) for accurate signature.",
            ["builtins.RuntimeError.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["builtins.__build_class__"] = "__build_class__(func, name, /, *bases, [metaclass], **kwds) -> class\n\nInternal helper function used by the class statement.",
            ["builtins.__import__"] = "__import__($module, /, name, globals=None, locals=None, fromlist=(),\n           level=0)\n--\n\nImport a module.\n\nBecause this function is meant for use by the Python\ninterpreter and not for general use, it is better to use\nimportlib.import_module() to programmatically import a module.\n\nThe globals argument is only used to determine the context;\nthey are not modified.  The locals argument is unused.  The fromlist\nshould be a list of names to emulate ``from name import ...``, or an\nempty list to emulate ``import name``.\nWhen importing a module from a package, note that __import__('A.B', ...)\nreturns package A when fromlist is empty, but its submodule B when\nfromlist is not empty.  The level argument is used to determine whether to\nperform absolute or relative imports: 0 is absolute, while a positive number\nis the number of parent directories to search relative to the current module.",
            ["builtins.abs"] = "abs($module, x, /)\n--\n\nReturn the absolute value of the argument.",
            ["builtins.aiter"] = "aiter($module, async_iterable, /)\n--\n\nReturn an AsyncIterator for an AsyncIterable object.",
            ["builtins.all"] = "all($module, iterable, /)\n--\n\nReturn True if bool(x) is True for all values x in the iterable.\n\nIf the iterable is empty, return True.",
            ["builtins.anext"] = "anext($module, aiterator, default=<unrepresentable>, /)\n--\n\nasync anext(aiterator[, default])\n\nReturn the next item from the async iterator.  If default is given and the async\niterator is exhausted, it is returned instead of raising StopAsyncIteration.",
            ["builtins.any"] = "any($module, iterable, /)\n--\n\nReturn True if bool(x) is True for any x in the iterable.\n\nIf the iterable is empty, return False.",
            ["builtins.ascii"] = "ascii($module, obj, /)\n--\n\nReturn an ASCII-only representation of an object.\n\nAs repr(), return a string containing a printable representation of an\nobject, but escape the non-ASCII characters in the string returned by\nrepr() using \\\\x, \\\\u or \\\\U escapes. This generates a string similar\nto that returned by repr() in Python 2.",
            ["builtins.bin"] = "bin($module, number, /)\n--\n\nReturn the binary representation of an integer.\n\n   >>> bin(2796202)\n   '0b1010101010101010101010'",
            ["builtins.breakpoint"] = "breakpoint(*args, **kws)\n\nCall sys.breakpointhook(*args, **kws).  sys.breakpointhook() must accept\nwhatever arguments are passed.\n\nBy default, this drops you into the pdb debugger.",
            ["builtins.callable"] = "callable($module, obj, /)\n--\n\nReturn whether the object is callable (i.e., some kind of function).\n\nNote that classes are callable, as are instances of classes with a\n__call__() method.",
            ["builtins.chr"] = "chr($module, i, /)\n--\n\nReturn a Unicode string of one character with ordinal i; 0 <= i <= 0x10ffff.",
            ["builtins.compile"] = "compile($module, /, source, filename, mode, flags=0,\n        dont_inherit=False, optimize=-1, *, _feature_version=-1)\n--\n\nCompile source into a code object that can be executed by exec() or eval().\n\nThe source code may represent a Python module, statement or expression.\nThe filename will be used for run-time error messages.\nThe mode must be 'exec' to compile a module, 'single' to compile a\nsingle (interactive) statement, or 'eval' to compile an expression.\nThe flags argument, if present, controls which future statements influence\nthe compilation of the code.\nThe dont_inherit argument, if true, stops the compilation inheriting\nthe effects of any future statements in effect in the code calling\ncompile; if absent or false these statements do influence the compilation,\nin addition to any features explicitly specified.",
            ["builtins.copyright"] = "interactive prompt objects for printing the license text, a list of\n    contributors and the copyright notice.",
            ["builtins.credits"] = "interactive prompt objects for printing the license text, a list of\n    contributors and the copyright notice.",
            ["builtins.delattr"] = "delattr($module, obj, name, /)\n--\n\nDeletes the named attribute from the given object.\n\ndelattr(x, 'y') is equivalent to ``del x.y``",
            ["builtins.dir"] = "dir([object]) -> list of strings\n\nIf called without an argument, return the names in the current scope.\nElse, return an alphabetized list of names comprising (some of) the attributes\nof the given object, and of attributes reachable from it.\nIf the object supplies a method named __dir__, it will be used; otherwise\nthe default dir() logic is used and returns:\n  for a module object: the module's attributes.\n  for a class object:  its attributes, and recursively the attributes\n    of its bases.\n  for any other object: its attributes, its class's attributes, and\n    recursively the attributes of its class's base classes.",
            ["builtins.divmod"] = "divmod($module, x, y, /)\n--\n\nReturn the tuple (x//y, x%y).  Invariant: div*y + mod == x.",
            ["builtins.eval"] = "eval($module, source, globals=None, locals=None, /)\n--\n\nEvaluate the given source in the context of globals and locals.\n\nThe source may be a string representing a Python expression\nor a code object as returned by compile().\nThe globals must be a dictionary and locals can be any mapping,\ndefaulting to the current globals and locals.\nIf only globals is given, locals defaults to it.",
            ["builtins.exec"] = "exec($module, source, globals=None, locals=None, /, *, closure=None)\n--\n\nExecute the given source in the context of globals and locals.\n\nThe source may be a string representing one or more Python statements\nor a code object as returned by compile().\nThe globals must be a dictionary and locals can be any mapping,\ndefaulting to the current globals and locals.\nIf only globals is given, locals defaults to it.\nThe closure must be a tuple of cellvars, and can only be used\nwhen source is a code object requiring exactly that many cellvars.",
            ["builtins.format"] = "format($module, value, format_spec='', /)\n--\n\nReturn type(value).__format__(value, format_spec)\n\nMany built-in types implement format_spec according to the\nFormat Specification Mini-language. See help('FORMATTING').\n\nIf type(value) does not supply a method named __format__\nand format_spec is empty, then str(value) is returned.\nSee also help('SPECIALMETHODS').",
            ["builtins.getattr"] = "getattr(object, name[, default]) -> value\n\nGet a named attribute from an object; getattr(x, 'y') is equivalent to x.y.\nWhen a default argument is given, it is returned when the attribute doesn't\nexist; without it, an exception is raised in that case.",
            ["builtins.globals"] = "globals($module, /)\n--\n\nReturn the dictionary containing the current scope's global variables.\n\nNOTE: Updates to this dictionary *will* affect name lookups in the current\nglobal scope and vice-versa.",
            ["builtins.hasattr"] = "hasattr($module, obj, name, /)\n--\n\nReturn whether the object has an attribute with the given name.\n\nThis is done by calling getattr(obj, name) and catching AttributeError.",
            ["builtins.hash"] = "hash($module, obj, /)\n--\n\nReturn the hash value for the given object.\n\nTwo objects that compare equal must also have the same hash value, but the\nreverse is not necessarily true.",
            ["builtins.help"] = "Define the builtin 'help'.\n\n    This is a wrapper around pydoc.help that provides a helpful message\n    when 'help' is typed at the Python interactive prompt.\n\n    Calling help() at the Python prompt starts an interactive help session.\n    Calling help(thing) prints help for the python object 'thing'.\n    ",
            ["builtins.hex"] = "hex($module, number, /)\n--\n\nReturn the hexadecimal representation of an integer.\n\n   >>> hex(12648430)\n   '0xc0ffee'",
            ["builtins.id"] = "id($module, obj, /)\n--\n\nReturn the identity of an object.\n\nThis is guaranteed to be unique among simultaneously existing objects.\n(CPython uses the object's memory address.)",
            ["builtins.input"] = "input($module, prompt='', /)\n--\n\nRead a string from standard input.  The trailing newline is stripped.\n\nThe prompt string, if given, is printed to standard output without a\ntrailing newline before reading input.\n\nIf the user hits EOF (*nix: Ctrl-D, Windows: Ctrl-Z+Return), raise EOFError.\nOn *nix systems, readline is used if available.",
            ["builtins.isinstance"] = "isinstance($module, obj, class_or_tuple, /)\n--\n\nReturn whether an object is an instance of a class or of a subclass thereof.\n\nA tuple, as in ``isinstance(x, (A, B, ...))``, may be given as the target to\ncheck against. This is equivalent to ``isinstance(x, A) or isinstance(x, B)\nor ...`` etc.",
            ["builtins.issubclass"] = "issubclass($module, cls, class_or_tuple, /)\n--\n\nReturn whether 'cls' is derived from another class or is the same class.\n\nA tuple, as in ``issubclass(x, (A, B, ...))``, may be given as the target to\ncheck against. This is equivalent to ``issubclass(x, A) or issubclass(x, B)\nor ...``.",
            ["builtins.iter"] = "iter(iterable) -> iterator\niter(callable, sentinel) -> iterator\n\nGet an iterator from an object.  In the first form, the argument must\nsupply its own iterator, or be a sequence.\nIn the second form, the callable is called until it returns the sentinel.",
            ["builtins.len"] = "len($module, obj, /)\n--\n\nReturn the number of items in a container.",
            ["builtins.license"] = "interactive prompt objects for printing the license text, a list of\n    contributors and the copyright notice.",
            ["builtins.locals"] = "locals($module, /)\n--\n\nReturn a dictionary containing the current scope's local variables.\n\nNOTE: Whether or not updates to this dictionary will affect name lookups in\nthe local scope and vice-versa is *implementation dependent* and not\ncovered by any backwards compatibility guarantees.",
            ["builtins.max"] = "max(iterable, *[, default=obj, key=func]) -> value\nmax(arg1, arg2, *args, *[, key=func]) -> value\n\nWith a single iterable argument, return its biggest item. The\ndefault keyword-only argument specifies an object to return if\nthe provided iterable is empty.\nWith two or more arguments, return the largest argument.",
            ["builtins.min"] = "min(iterable, *[, default=obj, key=func]) -> value\nmin(arg1, arg2, *args, *[, key=func]) -> value\n\nWith a single iterable argument, return its smallest item. The\ndefault keyword-only argument specifies an object to return if\nthe provided iterable is empty.\nWith two or more arguments, return the smallest argument.",
            ["builtins.next"] = "next(iterator[, default])\n\nReturn the next item from the iterator. If default is given and the iterator\nis exhausted, it is returned instead of raising StopIteration.",
            ["builtins.oct"] = "oct($module, number, /)\n--\n\nReturn the octal representation of an integer.\n\n   >>> oct(342391)\n   '0o1234567'",
            ["builtins.open"] = "open($module, /, file, mode='r', buffering=-1, encoding=None,\n     errors=None, newline=None, closefd=True, opener=None)\n--\n\nOpen file and return a stream.  Raise OSError upon failure.\n\nfile is either a text or byte string giving the name (and the path\nif the file isn't in the current working directory) of the file to\nbe opened or an integer file descriptor of the file to be\nwrapped. (If a file descriptor is given, it is closed when the\nreturned I/O object is closed, unless closefd is set to False.)\n\nmode is an optional string that specifies the mode in which the file\nis opened. It defaults to 'r' which means open for reading in text\nmode.  Other common values are 'w' for writing (truncating the file if\nit already exists), 'x' for creating and writing to a new file, and\n'a' for appending (which on some Unix systems, means that all writes\nappend to the end of the file regardless of the current seek position).\nIn text mode, if encoding is not specified the encoding used is platform\ndependent: locale.getencoding() is called to get the current locale encoding.\n(For reading and writing raw bytes use binary mode and leave encoding\nunspecified.) The available modes are:\n\n========= ===============================================================\nCharacter Meaning\n--------- ---------------------------------------------------------------\n'r'       open for reading (default)\n'w'       open for writing, truncating the file first\n'x'       create a new file and open it for writing\n'a'       open for writing, appending to the end of the file if it exists\n'b'       binary mode\n't'       text mode (default)\n'+'       open a disk file for updating (reading and writing)\n========= ===============================================================\n\nThe default mode is 'rt' (open for reading text). For binary random\naccess, the mode 'w+b' opens and truncates the file to 0 bytes, while\n'r+b' opens the file without truncation. The 'x' mode implies 'w' and\nraises an `FileExistsError` if the file already exists.\n\nPython distinguishes between files opened in binary and text modes,\neven when the underlying operating system doesn't. Files opened in\nbinary mode (appending 'b' to the mode argument) return contents as\nbytes objects without any decoding. In text mode (the default, or when\n't' is appended to the mode argument), the contents of the file are\nreturned as strings, the bytes having been first decoded using a\nplatform-dependent encoding or using the specified encoding if given.\n\nbuffering is an optional integer used to set the buffering policy.\nPass 0 to switch buffering off (only allowed in binary mode), 1 to select\nline buffering (only usable in text mode), and an integer > 1 to indicate\nthe size of a fixed-size chunk buffer.  When no buffering argument is\ngiven, the default buffering policy works as follows:\n\n* Binary files are buffered in fixed-size chunks; the size of the buffer\n  is chosen using a heuristic trying to determine the underlying device's\n  \"block size\" and falling back on `io.DEFAULT_BUFFER_SIZE`.\n  On many systems, the buffer will typically be 4096 or 8192 bytes long.\n\n* \"Interactive\" text files (files for which isatty() returns True)\n  use line buffering.  Other text files use the policy described above\n  for binary files.\n\nencoding is the name of the encoding used to decode or encode the\nfile. This should only be used in text mode. The default encoding is\nplatform dependent, but any encoding supported by Python can be\npassed.  See the codecs module for the list of supported encodings.\n\nerrors is an optional string that specifies how encoding errors are to\nbe handled---this argument should not be used in binary mode. Pass\n'strict' to raise a ValueError exception if there is an encoding error\n(the default of None has the same effect), or pass 'ignore' to ignore\nerrors. (Note that ignoring encoding errors can lead to data loss.)\nSee the documentation for codecs.register or run 'help(codecs.Codec)'\nfor a list of the permitted encoding error strings.\n\nnewline controls how universal newlines works (it only applies to text\nmode). It can be None, '', '\\n', '\\r', and '\\r\\n'.  It works as\nfollows:\n\n* On input, if newline is None, universal newlines mode is\n  enabled. Lines in the input can end in '\\n', '\\r', or '\\r\\n', and\n  these are translated into '\\n' before being returned to the\n  caller. If it is '', universal newline mode is enabled, but line\n  endings are returned to the caller untranslated. If it has any of\n  the other legal values, input lines are only terminated by the given\n  string, and the line ending is returned to the caller untranslated.\n\n* On output, if newline is None, any '\\n' characters written are\n  translated to the system default line separator, os.linesep. If\n  newline is '' or '\\n', no translation takes place. If newline is any\n  of the other legal values, any '\\n' characters written are translated\n  to the given string.\n\nIf closefd is False, the underlying file descriptor will be kept open\nwhen the file is closed. This does not work when a file name is given\nand must be True in that case.\n\nA custom opener can be used by passing a callable as *opener*. The\nunderlying file descriptor for the file object is then obtained by\ncalling *opener* with (*file*, *flags*). *opener* must return an open\nfile descriptor (passing os.open as *opener* results in functionality\nsimilar to passing None).\n\nopen() returns a file object whose type depends on the mode, and\nthrough which the standard file operations such as reading and writing\nare performed. When open() is used to open a file in a text mode ('w',\n'r', 'wt', 'rt', etc.), it returns a TextIOWrapper. When used to open\na file in a binary mode, the returned class varies: in read binary\nmode, it returns a BufferedReader; in write binary and append binary\nmodes, it returns a BufferedWriter, and in read/write mode, it returns\na BufferedRandom.\n\nIt is also possible to use a string or bytearray as a file for both\nreading and writing. For strings StringIO can be used like a file\nopened in a text mode, and for bytes a BytesIO can be used like a file\nopened in a binary mode.",
            ["builtins.ord"] = "ord($module, c, /)\n--\n\nReturn the Unicode code point for a one-character string.",
            ["builtins.pow"] = "pow($module, /, base, exp, mod=None)\n--\n\nEquivalent to base**exp with 2 arguments or base**exp % mod with 3 arguments\n\nSome types, such as ints, are able to use a more efficient algorithm when\ninvoked using the three argument form.",
            ["builtins.print"] = "print($module, /, *args, sep=' ', end='\\n', file=None, flush=False)\n--\n\nPrints the values to a stream, or to sys.stdout by default.\n\n  sep\n    string inserted between values, default a space.\n  end\n    string appended after the last value, default a newline.\n  file\n    a file-like object (stream); defaults to the current sys.stdout.\n  flush\n    whether to forcibly flush the stream.",
            ["builtins.repr"] = "repr($module, obj, /)\n--\n\nReturn the canonical string representation of the object.\n\nFor many object types, including most builtins, eval(repr(obj)) == obj.",
            ["builtins.round"] = "round($module, /, number, ndigits=None)\n--\n\nRound a number to a given precision in decimal digits.\n\nThe return value is an integer if ndigits is omitted or None.  Otherwise\nthe return value has the same type as the number.  ndigits may be negative.",
            ["builtins.setattr"] = "setattr($module, obj, name, value, /)\n--\n\nSets the named attribute on the given object to the specified value.\n\nsetattr(x, 'y', v) is equivalent to ``x.y = v``",
            ["builtins.sorted"] = "sorted($module, iterable, /, *, key=None, reverse=False)\n--\n\nReturn a new list containing all items from the iterable in ascending order.\n\nA custom key function can be supplied to customize the sort order, and the\nreverse flag can be set to request the result in descending order.",
            ["builtins.sum"] = "sum($module, iterable, /, start=0)\n--\n\nReturn the sum of a 'start' value (default: 0) plus an iterable of numbers\n\nWhen the iterable is empty, return the start value.\nThis function is intended specifically for use with numeric values and may\nreject non-numeric types.",
            ["builtins.vars"] = "vars([object]) -> dictionary\n\nWithout arguments, equivalent to locals().\nWith an argument, equivalent to object.__dict__.",
            ["bytearray"] = "bytearray(iterable_of_ints) -> bytearray\nbytearray(string, encoding[, errors]) -> bytearray\nbytearray(bytes_or_buffer) -> mutable copy of bytes_or_buffer\nbytearray(int) -> bytes array of size given by the parameter initialized with null bytes\nbytearray() -> empty bytes array\n\nConstruct a mutable bytearray object from:\n  - an iterable yielding integers in range(256)\n  - a text string encoded using the specified encoding\n  - a bytes or a buffer object\n  - any object implementing the buffer API.\n  - an integer",
            ["bytearray.__add__"] = "__add__($self, value, /)\n--\n\nReturn self+value.",
            ["bytearray.__alloc__"] = "B.__alloc__() -> int\n\nReturn the number of bytes actually allocated.",
            ["bytearray.__buffer__"] = "__buffer__($self, flags, /)\n--\n\nReturn a buffer object that exposes the underlying memory of the object.",
            ["bytearray.__contains__"] = "__contains__($self, key, /)\n--\n\nReturn bool(key in self).",
            ["bytearray.__delitem__"] = "__delitem__($self, key, /)\n--\n\nDelete self[key].",
            ["bytearray.__eq__"] = "__eq__($self, value, /)\n--\n\nReturn self==value.",
            ["bytearray.__ge__"] = "__ge__($self, value, /)\n--\n\nReturn self>=value.",
            ["bytearray.__getattribute__"] = "__getattribute__($self, name, /)\n--\n\nReturn getattr(self, name).",
            ["bytearray.__getitem__"] = "__getitem__($self, key, /)\n--\n\nReturn self[key].",
            ["bytearray.__gt__"] = "__gt__($self, value, /)\n--\n\nReturn self>value.",
            ["bytearray.__iadd__"] = "__iadd__($self, value, /)\n--\n\nImplement self+=value.",
            ["bytearray.__imul__"] = "__imul__($self, value, /)\n--\n\nImplement self*=value.",
            ["bytearray.__init__"] = "__init__($self, /, *args, **kwargs)\n--\n\nInitialize self.  See help(type(self)) for accurate signature.",
            ["bytearray.__iter__"] = "__iter__($self, /)\n--\n\nImplement iter(self).",
            ["bytearray.__le__"] = "__le__($self, value, /)\n--\n\nReturn self<=value.",
            ["bytearray.__len__"] = "__len__($self, /)\n--\n\nReturn len(self).",
            ["bytearray.__lt__"] = "__lt__($self, value, /)\n--\n\nReturn self<value.",
            ["bytearray.__mod__"] = "__mod__($self, value, /)\n--\n\nReturn self%value.",
            ["bytearray.__mul__"] = "__mul__($self, value, /)\n--\n\nReturn self*value.",
            ["bytearray.__ne__"] = "__ne__($self, value, /)\n--\n\nReturn self!=value.",
            ["bytearray.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["bytearray.__reduce__"] = "__reduce__($self, /)\n--\n\nReturn state information for pickling.",
            ["bytearray.__reduce_ex__"] = "__reduce_ex__($self, proto=0, /)\n--\n\nReturn state information for pickling.",
            ["bytearray.__release_buffer__"] = "__release_buffer__($self, buffer, /)\n--\n\nRelease the buffer object that exposes the underlying memory of the object.",
            ["bytearray.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["bytearray.__rmod__"] = "__rmod__($self, value, /)\n--\n\nReturn value%self.",
            ["bytearray.__rmul__"] = "__rmul__($self, value, /)\n--\n\nReturn value*self.",
            ["bytearray.__setitem__"] = "__setitem__($self, key, value, /)\n--\n\nSet self[key] to value.",
            ["bytearray.__sizeof__"] = "__sizeof__($self, /)\n--\n\nReturns the size of the bytearray object in memory, in bytes.",
            ["bytearray.__str__"] = "__str__($self, /)\n--\n\nReturn str(self).",
            ["bytearray.append"] = "append($self, item, /)\n--\n\nAppend a single item to the end of the bytearray.\n\n  item\n    The item to be appended.",
            ["bytearray.capitalize"] = "B.capitalize() -> copy of B\n\nReturn a copy of B with only its first character capitalized (ASCII)\nand the rest lower-cased.",
            ["bytearray.center"] = "center($self, width, fillchar=b' ', /)\n--\n\nReturn a centered string of length width.\n\nPadding is done using the specified fill character.",
            ["bytearray.clear"] = "clear($self, /)\n--\n\nRemove all items from the bytearray.",
            ["bytearray.copy"] = "copy($self, /)\n--\n\nReturn a copy of B.",
            ["bytearray.count"] = "B.count(sub[, start[, end]]) -> int\n\nReturn the number of non-overlapping occurrences of subsection sub in\nbytes B[start:end].  Optional arguments start and end are interpreted\nas in slice notation.",
            ["bytearray.decode"] = "decode($self, /, encoding='utf-8', errors='strict')\n--\n\nDecode the bytearray using the codec registered for encoding.\n\n  encoding\n    The encoding with which to decode the bytearray.\n  errors\n    The error handling scheme to use for the handling of decoding errors.\n    The default is 'strict' meaning that decoding errors raise a\n    UnicodeDecodeError. Other possible values are 'ignore' and 'replace'\n    as well as any other name registered with codecs.register_error that\n    can handle UnicodeDecodeErrors.",
            ["bytearray.endswith"] = "B.endswith(suffix[, start[, end]]) -> bool\n\nReturn True if B ends with the specified suffix, False otherwise.\nWith optional start, test B beginning at that position.\nWith optional end, stop comparing B at that position.\nsuffix can also be a tuple of bytes to try.",
            ["bytearray.expandtabs"] = "expandtabs($self, /, tabsize=8)\n--\n\nReturn a copy where all tab characters are expanded using spaces.\n\nIf tabsize is not given, a tab size of 8 characters is assumed.",
            ["bytearray.extend"] = "extend($self, iterable_of_ints, /)\n--\n\nAppend all the items from the iterator or sequence to the end of the bytearray.\n\n  iterable_of_ints\n    The iterable of items to append.",
            ["bytearray.find"] = "B.find(sub[, start[, end]]) -> int\n\nReturn the lowest index in B where subsection sub is found,\nsuch that sub is contained within B[start,end].  Optional\narguments start and end are interpreted as in slice notation.\n\nReturn -1 on failure.",
            ["bytearray.fromhex"] = "fromhex($type, string, /)\n--\n\nCreate a bytearray object from a string of hexadecimal numbers.\n\nSpaces between two numbers are accepted.\nExample: bytearray.fromhex('B9 01EF') -> bytearray(b'\\\\xb9\\\\x01\\\\xef')",
            ["bytearray.hex"] = "hex($self, /, sep=<unrepresentable>, bytes_per_sep=1)\n--\n\nCreate a string of hexadecimal numbers from a bytearray object.\n\n  sep\n    An optional single character or byte to separate hex bytes.\n  bytes_per_sep\n    How many bytes between separators.  Positive values count from the\n    right, negative values count from the left.\n\nExample:\n>>> value = bytearray([0xb9, 0x01, 0xef])\n>>> value.hex()\n'b901ef'\n>>> value.hex(':')\n'b9:01:ef'\n>>> value.hex(':', 2)\n'b9:01ef'\n>>> value.hex(':', -2)\n'b901:ef'",
            ["bytearray.index"] = "B.index(sub[, start[, end]]) -> int\n\nReturn the lowest index in B where subsection sub is found,\nsuch that sub is contained within B[start,end].  Optional\narguments start and end are interpreted as in slice notation.\n\nRaises ValueError when the subsection is not found.",
            ["bytearray.insert"] = "insert($self, index, item, /)\n--\n\nInsert a single item into the bytearray before the given index.\n\n  index\n    The index where the value is to be inserted.\n  item\n    The item to be inserted.",
            ["bytearray.isalnum"] = "B.isalnum() -> bool\n\nReturn True if all characters in B are alphanumeric\nand there is at least one character in B, False otherwise.",
            ["bytearray.isalpha"] = "B.isalpha() -> bool\n\nReturn True if all characters in B are alphabetic\nand there is at least one character in B, False otherwise.",
            ["bytearray.isascii"] = "B.isascii() -> bool\n\nReturn True if B is empty or all characters in B are ASCII,\nFalse otherwise.",
            ["bytearray.isdigit"] = "B.isdigit() -> bool\n\nReturn True if all characters in B are digits\nand there is at least one character in B, False otherwise.",
            ["bytearray.islower"] = "B.islower() -> bool\n\nReturn True if all cased characters in B are lowercase and there is\nat least one cased character in B, False otherwise.",
            ["bytearray.isspace"] = "B.isspace() -> bool\n\nReturn True if all characters in B are whitespace\nand there is at least one character in B, False otherwise.",
            ["bytearray.istitle"] = "B.istitle() -> bool\n\nReturn True if B is a titlecased string and there is at least one\ncharacter in B, i.e. uppercase characters may only follow uncased\ncharacters and lowercase characters only cased ones. Return False\notherwise.",
            ["bytearray.isupper"] = "B.isupper() -> bool\n\nReturn True if all cased characters in B are uppercase and there is\nat least one cased character in B, False otherwise.",
            ["bytearray.join"] = "join($self, iterable_of_bytes, /)\n--\n\nConcatenate any number of bytes/bytearray objects.\n\nThe bytearray whose method is called is inserted in between each pair.\n\nThe result is returned as a new bytearray object.",
            ["bytearray.ljust"] = "ljust($self, width, fillchar=b' ', /)\n--\n\nReturn a left-justified string of length width.\n\nPadding is done using the specified fill character.",
            ["bytearray.lower"] = "B.lower() -> copy of B\n\nReturn a copy of B with all ASCII characters converted to lowercase.",
            ["bytearray.lstrip"] = "lstrip($self, bytes=None, /)\n--\n\nStrip leading bytes contained in the argument.\n\nIf the argument is omitted or None, strip leading ASCII whitespace.",
            ["bytearray.maketrans"] = "staticmethod(function) -> method\n\nConvert a function to be a static method.\n\nA static method does not receive an implicit first argument.\nTo declare a static method, use this idiom:\n\n     class C:\n         @staticmethod\n         def f(arg1, arg2, argN):\n             ...\n\nIt can be called either on the class (e.g. C.f()) or on an instance\n(e.g. C().f()). Both the class and the instance are ignored, and\nneither is passed implicitly as the first argument to the method.\n\nStatic methods in Python are similar to those found in Java or C++.\nFor a more advanced concept, see the classmethod builtin.",
            ["bytearray.partition"] = "partition($self, sep, /)\n--\n\nPartition the bytearray into three parts using the given separator.\n\nThis will search for the separator sep in the bytearray. If the separator is\nfound, returns a 3-tuple containing the part before the separator, the\nseparator itself, and the part after it as new bytearray objects.\n\nIf the separator is not found, returns a 3-tuple containing the copy of the\noriginal bytearray object and two empty bytearray objects.",
            ["bytearray.pop"] = "pop($self, index=-1, /)\n--\n\nRemove and return a single item from B.\n\n  index\n    The index from where to remove the item.\n    -1 (the default value) means remove the last item.\n\nIf no index argument is given, will pop the last item.",
            ["bytearray.remove"] = "remove($self, value, /)\n--\n\nRemove the first occurrence of a value in the bytearray.\n\n  value\n    The value to remove.",
            ["bytearray.removeprefix"] = "removeprefix($self, prefix, /)\n--\n\nReturn a bytearray with the given prefix string removed if present.\n\nIf the bytearray starts with the prefix string, return\nbytearray[len(prefix):].  Otherwise, return a copy of the original\nbytearray.",
            ["bytearray.removesuffix"] = "removesuffix($self, suffix, /)\n--\n\nReturn a bytearray with the given suffix string removed if present.\n\nIf the bytearray ends with the suffix string and that suffix is not\nempty, return bytearray[:-len(suffix)].  Otherwise, return a copy of\nthe original bytearray.",
            ["bytearray.replace"] = "replace($self, old, new, count=-1, /)\n--\n\nReturn a copy with all occurrences of substring old replaced by new.\n\n  count\n    Maximum number of occurrences to replace.\n    -1 (the default value) means replace all occurrences.\n\nIf the optional argument count is given, only the first count occurrences are\nreplaced.",
            ["bytearray.reverse"] = "reverse($self, /)\n--\n\nReverse the order of the values in B in place.",
            ["bytearray.rfind"] = "B.rfind(sub[, start[, end]]) -> int\n\nReturn the highest index in B where subsection sub is found,\nsuch that sub is contained within B[start,end].  Optional\narguments start and end are interpreted as in slice notation.\n\nReturn -1 on failure.",
            ["bytearray.rindex"] = "B.rindex(sub[, start[, end]]) -> int\n\nReturn the highest index in B where subsection sub is found,\nsuch that sub is contained within B[start,end].  Optional\narguments start and end are interpreted as in slice notation.\n\nRaise ValueError when the subsection is not found.",
            ["bytearray.rjust"] = "rjust($self, width, fillchar=b' ', /)\n--\n\nReturn a right-justified string of length width.\n\nPadding is done using the specified fill character.",
            ["bytearray.rpartition"] = "rpartition($self, sep, /)\n--\n\nPartition the bytearray into three parts using the given separator.\n\nThis will search for the separator sep in the bytearray, starting at the end.\nIf the separator is found, returns a 3-tuple containing the part before the\nseparator, the separator itself, and the part after it as new bytearray\nobjects.\n\nIf the separator is not found, returns a 3-tuple containing two empty bytearray\nobjects and the copy of the original bytearray object.",
            ["bytearray.rsplit"] = "rsplit($self, /, sep=None, maxsplit=-1)\n--\n\nReturn a list of the sections in the bytearray, using sep as the delimiter.\n\n  sep\n    The delimiter according which to split the bytearray.\n    None (the default value) means split on ASCII whitespace characters\n    (space, tab, return, newline, formfeed, vertical tab).\n  maxsplit\n    Maximum number of splits to do.\n    -1 (the default value) means no limit.\n\nSplitting is done starting at the end of the bytearray and working to the front.",
            ["bytearray.rstrip"] = "rstrip($self, bytes=None, /)\n--\n\nStrip trailing bytes contained in the argument.\n\nIf the argument is omitted or None, strip trailing ASCII whitespace.",
            ["bytearray.split"] = "split($self, /, sep=None, maxsplit=-1)\n--\n\nReturn a list of the sections in the bytearray, using sep as the delimiter.\n\n  sep\n    The delimiter according which to split the bytearray.\n    None (the default value) means split on ASCII whitespace characters\n    (space, tab, return, newline, formfeed, vertical tab).\n  maxsplit\n    Maximum number of splits to do.\n    -1 (the default value) means no limit.",
            ["bytearray.splitlines"] = "splitlines($self, /, keepends=False)\n--\n\nReturn a list of the lines in the bytearray, breaking at line boundaries.\n\nLine breaks are not included in the resulting list unless keepends is given and\ntrue.",
            ["bytearray.startswith"] = "B.startswith(prefix[, start[, end]]) -> bool\n\nReturn True if B starts with the specified prefix, False otherwise.\nWith optional start, test B beginning at that position.\nWith optional end, stop comparing B at that position.\nprefix can also be a tuple of bytes to try.",
            ["bytearray.strip"] = "strip($self, bytes=None, /)\n--\n\nStrip leading and trailing bytes contained in the argument.\n\nIf the argument is omitted or None, strip leading and trailing ASCII whitespace.",
            ["bytearray.swapcase"] = "B.swapcase() -> copy of B\n\nReturn a copy of B with uppercase ASCII characters converted\nto lowercase ASCII and vice versa.",
            ["bytearray.title"] = "B.title() -> copy of B\n\nReturn a titlecased version of B, i.e. ASCII words start with uppercase\ncharacters, all remaining cased characters have lowercase.",
            ["bytearray.translate"] = "translate($self, table, /, delete=b'')\n--\n\nReturn a copy with each character mapped by the given translation table.\n\n  table\n    Translation table, which must be a bytes object of length 256.\n\nAll characters occurring in the optional argument delete are removed.\nThe remaining characters are mapped through the given translation table.",
            ["bytearray.upper"] = "B.upper() -> copy of B\n\nReturn a copy of B with all ASCII characters converted to uppercase.",
            ["bytearray.zfill"] = "zfill($self, width, /)\n--\n\nPad a numeric string with zeros on the left, to fill a field of the given width.\n\nThe original string is never truncated.",
            ["bytes"] = "bytes(iterable_of_ints) -> bytes\nbytes(string, encoding[, errors]) -> bytes\nbytes(bytes_or_buffer) -> immutable copy of bytes_or_buffer\nbytes(int) -> bytes object of size given by the parameter initialized with null bytes\nbytes() -> empty bytes object\n\nConstruct an immutable array of bytes from:\n  - an iterable yielding integers in range(256)\n  - a text string encoded using the specified encoding\n  - any object implementing the buffer API.\n  - an integer",
            ["bytes.__add__"] = "__add__($self, value, /)\n--\n\nReturn self+value.",
            ["bytes.__buffer__"] = "__buffer__($self, flags, /)\n--\n\nReturn a buffer object that exposes the underlying memory of the object.",
            ["bytes.__bytes__"] = "__bytes__($self, /)\n--\n\nConvert this value to exact type bytes.",
            ["bytes.__contains__"] = "__contains__($self, key, /)\n--\n\nReturn bool(key in self).",
            ["bytes.__eq__"] = "__eq__($self, value, /)\n--\n\nReturn self==value.",
            ["bytes.__ge__"] = "__ge__($self, value, /)\n--\n\nReturn self>=value.",
            ["bytes.__getattribute__"] = "__getattribute__($self, name, /)\n--\n\nReturn getattr(self, name).",
            ["bytes.__getitem__"] = "__getitem__($self, key, /)\n--\n\nReturn self[key].",
            ["bytes.__gt__"] = "__gt__($self, value, /)\n--\n\nReturn self>value.",
            ["bytes.__hash__"] = "__hash__($self, /)\n--\n\nReturn hash(self).",
            ["bytes.__iter__"] = "__iter__($self, /)\n--\n\nImplement iter(self).",
            ["bytes.__le__"] = "__le__($self, value, /)\n--\n\nReturn self<=value.",
            ["bytes.__len__"] = "__len__($self, /)\n--\n\nReturn len(self).",
            ["bytes.__lt__"] = "__lt__($self, value, /)\n--\n\nReturn self<value.",
            ["bytes.__mod__"] = "__mod__($self, value, /)\n--\n\nReturn self%value.",
            ["bytes.__mul__"] = "__mul__($self, value, /)\n--\n\nReturn self*value.",
            ["bytes.__ne__"] = "__ne__($self, value, /)\n--\n\nReturn self!=value.",
            ["bytes.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["bytes.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["bytes.__rmod__"] = "__rmod__($self, value, /)\n--\n\nReturn value%self.",
            ["bytes.__rmul__"] = "__rmul__($self, value, /)\n--\n\nReturn value*self.",
            ["bytes.__str__"] = "__str__($self, /)\n--\n\nReturn str(self).",
