            ["math.__doc__"] = "This module provides access to the mathematical functions\ndefined by the C standard.",
            ["math.acos"] = "acos($module, x, /)\n--\n\nReturn the arc cosine (measured in radians) of x.\n\nThe result is between 0 and pi.",
            ["math.acosh"] = "acosh($module, x, /)\n--\n\nReturn the inverse hyperbolic cosine of x.",
            ["math.asin"] = "asin($module, x, /)\n--\n\nReturn the arc sine (measured in radians) of x.\n\nThe result is between -pi/2 and pi/2.",
            ["math.asinh"] = "asinh($module, x, /)\n--\n\nReturn the inverse hyperbolic sine of x.",
            ["math.atan"] = "atan($module, x, /)\n--\n\nReturn the arc tangent (measured in radians) of x.\n\nThe result is between -pi/2 and pi/2.",
            ["math.atan2"] = "atan2($module, y, x, /)\n--\n\nReturn the arc tangent (measured in radians) of y/x.\n\nUnlike atan(y/x), the signs of both x and y are considered.",
            ["math.atanh"] = "atanh($module, x, /)\n--\n\nReturn the inverse hyperbolic tangent of x.",
            ["math.cbrt"] = "cbrt($module, x, /)\n--\n\nReturn the cube root of x.",
            ["math.ceil"] = "ceil($module, x, /)\n--\n\nReturn the ceiling of x as an Integral.\n\nThis is the smallest integer >= x.",
            ["math.comb"] = "comb($module, n, k, /)\n--\n\nNumber of ways to choose k items from n items without repetition and without order.\n\nEvaluates to n! / (k! * (n - k)!) when k <= n and evaluates\nto zero when k > n.\n\nAlso called the binomial coefficient because it is equivalent\nto the coefficient of k-th term in polynomial expansion of the\nexpression (1 + x)**n.\n\nRaises TypeError if either of the arguments are not integers.\nRaises ValueError if either of the arguments are negative.",
            ["math.copysign"] = "copysign($module, x, y, /)\n--\n\nReturn a float with the magnitude (absolute value) of x but the sign of y.\n\nOn platforms that support signed zeros, copysign(1.0, -0.0)\nreturns -1.0.\n",
            ["math.cos"] = "cos($module, x, /)\n--\n\nReturn the cosine of x (measured in radians).",
            ["math.cosh"] = "cosh($module, x, /)\n--\n\nReturn the hyperbolic cosine of x.",
            ["math.degrees"] = "degrees($module, x, /)\n--\n\nConvert angle x from radians to degrees.",
            ["math.dist"] = "dist($module, p, q, /)\n--\n\nReturn the Euclidean distance between two points p and q.\n\nThe points should be specified as sequences (or iterables) of\ncoordinates.  Both inputs must have the same dimension.\n\nRoughly equivalent to:\n    sqrt(sum((px - qx) ** 2.0 for px, qx in zip(p, q)))",
            ["math.erf"] = "erf($module, x, /)\n--\n\nError function at x.",
            ["math.erfc"] = "erfc($module, x, /)\n--\n\nComplementary error function at x.",
            ["math.exp"] = "exp($module, x, /)\n--\n\nReturn e raised to the power of x.",
            ["math.exp2"] = "exp2($module, x, /)\n--\n\nReturn 2 raised to the power of x.",
            ["math.expm1"] = "expm1($module, x, /)\n--\n\nReturn exp(x)-1.\n\nThis function avoids the loss of precision involved in the direct evaluation of exp(x)-1 for small x.",
            ["math.fabs"] = "fabs($module, x, /)\n--\n\nReturn the absolute value of the float x.",
            ["math.factorial"] = "factorial($module, n, /)\n--\n\nFind n!.\n\nRaise a ValueError if x is negative or non-integral.",
            ["math.floor"] = "floor($module, x, /)\n--\n\nReturn the floor of x as an Integral.\n\nThis is the largest integer <= x.",
            ["math.fmod"] = "fmod($module, x, y, /)\n--\n\nReturn fmod(x, y), according to platform C.\n\nx % y may differ.",
            ["math.frexp"] = "frexp($module, x, /)\n--\n\nReturn the mantissa and exponent of x, as pair (m, e).\n\nm is a float and e is an int, such that x = m * 2.**e.\nIf x is 0, m and e are both 0.  Else 0.5 <= abs(m) < 1.0.",
            ["math.fsum"] = "fsum($module, seq, /)\n--\n\nReturn an accurate floating-point sum of values in the iterable seq.\n\nAssumes IEEE-754 floating-point arithmetic.",
            ["math.gamma"] = "gamma($module, x, /)\n--\n\nGamma function at x.",
            ["math.gcd"] = "gcd($module, *integers)\n--\n\nGreatest Common Divisor.",
            ["math.hypot"] = "hypot(*coordinates) -> value\n\nMultidimensional Euclidean distance from the origin to a point.\n\nRoughly equivalent to:\n    sqrt(sum(x**2 for x in coordinates))\n\nFor a two dimensional point (x, y), gives the hypotenuse\nusing the Pythagorean theorem:  sqrt(x*x + y*y).\n\nFor example, the hypotenuse of a 3/4/5 right triangle is:\n\n    >>> hypot(3.0, 4.0)\n    5.0\n",
            ["math.isclose"] = "isclose($module, /, a, b, *, rel_tol=1e-09, abs_tol=0.0)\n--\n\nDetermine whether two floating-point numbers are close in value.\n\n  rel_tol\n    maximum difference for being considered \"close\", relative to the\n    magnitude of the input values\n  abs_tol\n    maximum difference for being considered \"close\", regardless of the\n    magnitude of the input values\n\nReturn True if a is close in value to b, and False otherwise.\n\nFor the values to be considered close, the difference between them\nmust be smaller than at least one of the tolerances.\n\n-inf, inf and NaN behave similarly to the IEEE 754 Standard.  That\nis, NaN is not close to anything, even itself.  inf and -inf are\nonly close to themselves.",
            ["math.isfinite"] = "isfinite($module, x, /)\n--\n\nReturn True if x is neither an infinity nor a NaN, and False otherwise.",
            ["math.isinf"] = "isinf($module, x, /)\n--\n\nReturn True if x is a positive or negative infinity, and False otherwise.",
            ["math.isnan"] = "isnan($module, x, /)\n--\n\nReturn True if x is a NaN (not a number), and False otherwise.",
            ["math.isqrt"] = "isqrt($module, n, /)\n--\n\nReturn the integer part of the square root of the input.",
            ["math.lcm"] = "lcm($module, *integers)\n--\n\nLeast Common Multiple.",
            ["math.ldexp"] = "ldexp($module, x, i, /)\n--\n\nReturn x * (2**i).\n\nThis is essentially the inverse of frexp().",
            ["math.lgamma"] = "lgamma($module, x, /)\n--\n\nNatural logarithm of absolute value of Gamma function at x.",
            ["math.log"] = "log(x, [base=math.e])\nReturn the logarithm of x to the given base.\n\nIf the base is not specified, returns the natural logarithm (base e) of x.",
            ["math.log10"] = "log10($module, x, /)\n--\n\nReturn the base 10 logarithm of x.",
            ["math.log1p"] = "log1p($module, x, /)\n--\n\nReturn the natural logarithm of 1+x (base e).\n\nThe result is computed in a way which is accurate for x near zero.",
            ["math.log2"] = "log2($module, x, /)\n--\n\nReturn the base 2 logarithm of x.",
            ["math.modf"] = "modf($module, x, /)\n--\n\nReturn the fractional and integer parts of x.\n\nBoth results carry the sign of x and are floats.",
            ["math.nextafter"] = "nextafter($module, x, y, /, *, steps=None)\n--\n\nReturn the floating-point value the given number of steps after x towards y.\n\nIf steps is not specified or is None, it defaults to 1.\n\nRaises a TypeError, if x or y is not a double, or if steps is not an integer.\nRaises ValueError if steps is negative.",
            ["math.perm"] = "perm($module, n, k=None, /)\n--\n\nNumber of ways to choose k items from n items without repetition and with order.\n\nEvaluates to n! / (n - k)! when k <= n and evaluates\nto zero when k > n.\n\nIf k is not specified or is None, then k defaults to n\nand the function returns n!.\n\nRaises TypeError if either of the arguments are not integers.\nRaises ValueError if either of the arguments are negative.",
            ["math.pow"] = "pow($module, x, y, /)\n--\n\nReturn x**y (x to the power of y).",
            ["math.prod"] = "prod($module, iterable, /, *, start=1)\n--\n\nCalculate the product of all the elements in the input iterable.\n\nThe default start value for the product is 1.\n\nWhen the iterable is empty, return the start value.  This function is\nintended specifically for use with numeric values and may reject\nnon-numeric types.",
            ["math.radians"] = "radians($module, x, /)\n--\n\nConvert angle x from degrees to radians.",
            ["math.remainder"] = "remainder($module, x, y, /)\n--\n\nDifference between x and the closest integer multiple of y.\n\nReturn x - n*y where n*y is the closest integer multiple of y.\nIn the case where x is exactly halfway between two multiples of\ny, the nearest even value of n is used. The result is always exact.",
            ["math.sin"] = "sin($module, x, /)\n--\n\nReturn the sine of x (measured in radians).",
            ["math.sinh"] = "sinh($module, x, /)\n--\n\nReturn the hyperbolic sine of x.",
            ["math.sqrt"] = "sqrt($module, x, /)\n--\n\nReturn the square root of x.",
            ["math.sumprod"] = "sumprod($module, p, q, /)\n--\n\nReturn the sum of products of values from two iterables p and q.\n\nRoughly equivalent to:\n\n    sum(itertools.starmap(operator.mul, zip(p, q, strict=True)))\n\nFor float and mixed int/float inputs, the intermediate products\nand sums are computed with extended precision.",
            ["math.tan"] = "tan($module, x, /)\n--\n\nReturn the tangent of x (measured in radians).",
            ["math.tanh"] = "tanh($module, x, /)\n--\n\nReturn the hyperbolic tangent of x.",
            ["math.trunc"] = "trunc($module, x, /)\n--\n\nTruncates the Real x to the nearest Integral toward 0.\n\nUses the __trunc__ magic method.",
            ["math.ulp"] = "ulp($module, x, /)\n--\n\nReturn the value of the least significant bit of the float x.",
            ["member_descriptor.__delete__"] = "__delete__($self, instance, /)\n--\n\nDelete an attribute of instance.",
            ["member_descriptor.__get__"] = "__get__($self, instance, owner=None, /)\n--\n\nReturn an attribute of instance, which is of type owner.",
